



begin;

do $$
declare
    v_falta text[] := array[]::text[];
    v_tabla text;
begin
    foreach v_tabla in array array[
        'perfiles_usuario','materiales','almacenes','ubicaciones_almacen','existencias_almacen',
        'movimientos','proyectos','proyecto_materiales','solicitudes_compra'
    ] loop
        if to_regclass('public.' || v_tabla) is null then
            v_falta := array_append(v_falta, v_tabla);
        end if;
    end loop;
    if coalesce(array_length(v_falta,1),0) > 0 then
        raise exception 'Faltan tablas del esquema base del CRM: %. Este SQL maestro actualiza la base actual; restaura primero el esquema base.', array_to_string(v_falta, ', ');
    end if;
end;
$$;

create table if not exists public.crm_migraciones(
    version text primary key,
    aplicada_at timestamptz not null default now()
);

commit;


begin;

alter table public.proyectos add column if not exists tipo_control text;
update public.proyectos
set tipo_control='materiales'
where tipo_control is null or btrim(tipo_control)='' or lower(tipo_control) not in ('materiales','presupuesto');
alter table public.proyectos alter column tipo_control set default 'materiales';
alter table public.proyectos alter column tipo_control set not null;

alter table public.proyectos add column if not exists presupuesto_planeado numeric(16,2) not null default 0;
alter table public.proyectos add column if not exists presupuesto_materiales numeric(16,2) not null default 0;
alter table public.proyectos add column if not exists presupuesto_sueldos numeric(16,2) not null default 0;
alter table public.proyectos add column if not exists updated_at timestamptz not null default now();

alter table public.proyectos drop constraint if exists proyectos_tipo_control_check_v30;
alter table public.proyectos add constraint proyectos_tipo_control_check_v30
check (tipo_control in ('materiales','presupuesto'));

notify pgrst,'reload schema';
commit;


begin;

alter table public.perfiles_usuario add column if not exists telefono text;
alter table public.perfiles_usuario add column if not exists puesto text;
alter table public.perfiles_usuario add column if not exists departamento text;
alter table public.perfiles_usuario add column if not exists foto_url text;
update public.perfiles_usuario
set rol = case
    when lower(btrim(coalesce(rol,''))) in ('administrador','admin','administracion','administración') then 'administrador'
    when lower(btrim(coalesce(rol,''))) in ('jefe_almacen','jefe almacen','jefe de almacen','jefe de almacén','responsable almacen','responsable de almacen') then 'jefe_almacen'
    when lower(btrim(coalesce(rol,''))) in ('almacen','almacén','almacenista','bodega','bodeguero') then 'almacen'
    when lower(btrim(coalesce(rol,''))) in ('compras','comprador','compradora','abastecimiento') then 'compras'
    when lower(btrim(coalesce(rol,''))) in ('proyectos','proyecto','project manager','lider de proyecto','líder de proyecto') then 'proyectos'
    when lower(btrim(coalesce(rol,''))) in ('planeacion','planeación','planeador','planeadora') then 'planeacion'
    when lower(btrim(coalesce(rol,''))) in ('coordinacion','coordinación','coordinador','coordinadora') then 'coordinacion'
    when lower(btrim(coalesce(rol,''))) in ('logistica','logística','logistico','logístico','logistica vehicular','logística vehicular') then 'logistica'
    when lower(btrim(coalesce(rol,''))) in ('recepcion','recepción','recepcionista','front desk','entrada principal','caseta','atencion a visitantes','atención a visitantes') then 'recepcion'
    when lower(btrim(coalesce(rol,''))) in ('rh','rrhh','recursos humanos','capital humano') then 'rh'
    when lower(btrim(coalesce(rol,''))) in ('finanzas','financiero','financiera','contabilidad') then 'finanzas'
    when lower(btrim(coalesce(rol,''))) in ('gerente_general','gerente general','gg','gerencia general','gerencia','direccion','dirección','director','directora') then 'gerente_general'
    when lower(btrim(coalesce(rol,''))) in ('subgerente','subgerencia','sg','sub gerente') then 'subgerente'
    when lower(btrim(coalesce(rol,''))) in ('tsi','sistemas','tecnologia','tecnología','tecnologias de la informacion','tecnologías de la información') then 'tsi'
    when lower(btrim(coalesce(rol,''))) in ('sky_demo','sky demo','sky','demo') then 'sky_demo'
    when lower(btrim(coalesce(rol,''))) in ('consulta','consultas','lector','lectura','solo lectura') then 'consulta'
    else 'consulta'
end;
alter table public.perfiles_usuario drop constraint if exists perfiles_usuario_rol_check;
alter table public.perfiles_usuario add constraint perfiles_usuario_rol_check
check (lower(btrim(rol)) in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','gerente_general','subgerente','tsi','sky_demo','consulta'));



create table if not exists public.rh_personal (
    id bigint generated by default as identity primary key,
    numero_empleado text not null unique,
    nombre text not null,
    apellidos text not null,
    correo text,
    telefono text,
    puesto text not null,
    departamento text not null,
    fecha_ingreso date,
    tipo_contrato text,
    estado text not null default 'activo',
    jefe_directo text,
    usuario_id uuid references auth.users(id) on delete set null,
    observaciones text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.rh_personal add column if not exists turno text;
alter table public.rh_personal add column if not exists fecha_fin_contrato date;
alter table public.rh_personal add column if not exists fecha_nacimiento date;
alter table public.rh_personal add column if not exists sexo text;
alter table public.rh_personal add column if not exists curp text;
alter table public.rh_personal add column if not exists rfc text;
alter table public.rh_personal add column if not exists nss text;
alter table public.rh_personal add column if not exists estado_civil text;
alter table public.rh_personal add column if not exists nacionalidad text;
alter table public.rh_personal add column if not exists correo_corporativo text;
alter table public.rh_personal add column if not exists domicilio text;
alter table public.rh_personal add column if not exists colonia text;
alter table public.rh_personal add column if not exists municipio text;
alter table public.rh_personal add column if not exists estado_residencia text;
alter table public.rh_personal add column if not exists codigo_postal text;
alter table public.rh_personal add column if not exists contacto_emergencia text;
alter table public.rh_personal add column if not exists parentesco_emergencia text;
alter table public.rh_personal add column if not exists telefono_emergencia text;
alter table public.rh_personal add column if not exists tipo_sangre text;
alter table public.rh_personal add column if not exists alergias text;
alter table public.rh_personal add column if not exists salario numeric(14,2);
alter table public.rh_personal add column if not exists banco text;
alter table public.rh_personal add column if not exists clabe text;
alter table public.rh_personal add column if not exists foto_url text;

alter table public.rh_personal drop constraint if exists rh_personal_estado_check;
alter table public.rh_personal add constraint rh_personal_estado_check check (estado in ('activo','vacaciones','incapacidad','suspendido','baja'));
create unique index if not exists rh_personal_numero_empleado_uq on public.rh_personal(lower(numero_empleado));
create index if not exists rh_personal_estado_idx on public.rh_personal(estado);
create index if not exists rh_personal_departamento_idx on public.rh_personal(departamento);
create index if not exists rh_personal_contrato_idx on public.rh_personal(fecha_fin_contrato);

create or replace function public.rh_actualizar_fecha()
returns trigger language plpgsql as $$
begin new.updated_at=now(); return new; end;
$$;
drop trigger if exists trg_rh_personal_actualizar_fecha on public.rh_personal;
create trigger trg_rh_personal_actualizar_fecha before update on public.rh_personal for each row execute function public.rh_actualizar_fecha();

alter table public.rh_personal enable row level security;
drop policy if exists "RH consulta personal" on public.rh_personal;
create policy "RH consulta personal" on public.rh_personal for select to authenticated using (
    usuario_id=auth.uid() or exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
drop policy if exists "RH administra personal" on public.rh_personal;
create policy "RH administra personal" on public.rh_personal for all to authenticated using (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
) with check (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
grant select,insert,update,delete on public.rh_personal to authenticated;
grant usage,select on sequence public.rh_personal_id_seq to authenticated;

create table if not exists public.rh_proyecto_asignaciones (
    id bigint generated by default as identity primary key,
    proyecto_numero text not null references public.proyectos(numero_proyecto) on update cascade on delete cascade,
    personal_id bigint not null references public.rh_personal(id) on update cascade on delete cascade,
    rol_proyecto text not null,
    fecha_inicio date not null default current_date,
    fecha_fin date,
    estado text not null default 'activo' check (estado in ('activo','finalizado','cancelado')),
    observaciones text,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(proyecto_numero,personal_id)
);
create index if not exists rh_asignaciones_proyecto_idx on public.rh_proyecto_asignaciones(proyecto_numero,estado);
create index if not exists rh_asignaciones_personal_idx on public.rh_proyecto_asignaciones(personal_id,estado);
drop trigger if exists trg_rh_proyecto_asignaciones_fecha on public.rh_proyecto_asignaciones;
create trigger trg_rh_proyecto_asignaciones_fecha before update on public.rh_proyecto_asignaciones for each row execute function public.rh_actualizar_fecha();

alter table public.rh_proyecto_asignaciones enable row level security;
drop policy if exists "Perfiles operativos consultan asignaciones RH" on public.rh_proyecto_asignaciones;
create policy "Perfiles operativos consultan asignaciones RH" on public.rh_proyecto_asignaciones for select to authenticated using (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh','jefe_almacen','almacen','proyectos'))
);
drop policy if exists "Solo RH administra asignaciones" on public.rh_proyecto_asignaciones;
create policy "Solo RH administra asignaciones" on public.rh_proyecto_asignaciones for all to authenticated using (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
) with check (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
grant select,insert,update,delete on public.rh_proyecto_asignaciones to authenticated;
grant usage,select on sequence public.rh_proyecto_asignaciones_id_seq to authenticated;

alter table public.proyectos enable row level security;
drop policy if exists "RH consulta proyectos" on public.proyectos;
create policy "RH consulta proyectos" on public.proyectos for select to authenticated using (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh','jefe_almacen','almacen','proyectos','finanzas','gerente_general','subgerente'))
);
drop policy if exists "RH administra proyectos" on public.proyectos;
create policy "RH administra proyectos" on public.proyectos for all to authenticated using (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
) with check (
    exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
grant select,insert,update,delete on public.proyectos to authenticated;

commit;


begin;

alter table public.rh_personal add column if not exists esquema_pago text not null default 'hora';
alter table public.rh_personal add column if not exists tarifa_pago numeric(14,2) not null default 0;
alter table public.rh_personal add column if not exists horas_jornada_diaria numeric(5,2) not null default 8;
alter table public.rh_personal add column if not exists dias_laborales_semana integer not null default 6;
alter table public.rh_personal add column if not exists horas_comida_diaria numeric(5,2) not null default 1;
alter table public.rh_personal add column if not exists salario_semanal_calculado numeric(14,2) not null default 0;

alter table public.rh_personal drop constraint if exists rh_personal_esquema_pago_check;
alter table public.rh_personal add constraint rh_personal_esquema_pago_check check (esquema_pago in ('hora','semana','confianza'));
alter table public.rh_personal drop constraint if exists rh_personal_dias_laborales_check;
alter table public.rh_personal add constraint rh_personal_dias_laborales_check check (dias_laborales_semana between 1 and 7);
alter table public.rh_personal drop constraint if exists rh_personal_horas_check;
alter table public.rh_personal add constraint rh_personal_horas_check check (horas_jornada_diaria >= 0 and horas_jornada_diaria <= 24 and horas_comida_diaria >= 0 and horas_comida_diaria <= 8);

update public.rh_personal
set esquema_pago = coalesce(nullif(esquema_pago,''),'semana'),
    tarifa_pago = case when coalesce(tarifa_pago,0)=0 then coalesce(salario,0) else tarifa_pago end,
    salario_semanal_calculado = case when coalesce(salario_semanal_calculado,0)=0 then coalesce(salario,0) else salario_semanal_calculado end;

commit;

select 'OK' as estado, count(*) as colaboradores from public.rh_personal;



begin;

create or replace function public.rh_co_actualizar_fecha()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create table if not exists public.co_proveedores (
  id bigint generated by default as identity primary key,
  clave text,
  razon_social text not null,
  nombre_comercial text,
  rfc text,
  contacto text,
  email text,
  telefono text,
  direccion text,
  categoria text,
  dias_credito integer not null default 0 check (dias_credito >= 0),
  moneda text not null default 'MXN' check (moneda in ('MXN','USD','EUR')),
  evaluacion numeric(5,2) check (evaluacion is null or (evaluacion >= 0 and evaluacion <= 100)),
  tiempo_entrega_dias integer check (tiempo_entrega_dias is null or tiempo_entrega_dias >= 0),
  estado text not null default 'activo' check (estado in ('activo','evaluacion','inactivo')),
  notas text,
  creado_por uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists co_proveedores_razon_social_uq on public.co_proveedores(lower(razon_social));
create unique index if not exists co_proveedores_clave_uq on public.co_proveedores(lower(clave)) where clave is not null and trim(clave) <> '';
create index if not exists co_proveedores_estado_idx on public.co_proveedores(estado);
create index if not exists co_proveedores_categoria_idx on public.co_proveedores(categoria);
drop trigger if exists trg_co_proveedores_actualizar_fecha on public.co_proveedores;
create trigger trg_co_proveedores_actualizar_fecha before update on public.co_proveedores for each row execute function public.rh_co_actualizar_fecha();

alter table public.co_proveedores enable row level security;
drop policy if exists "Compras consulta proveedores" on public.co_proveedores;
create policy "Compras consulta proveedores" on public.co_proveedores for select to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras','jefe_almacen','almacen'))
);
drop policy if exists "Compras administra proveedores" on public.co_proveedores;
create policy "Compras administra proveedores" on public.co_proveedores for all to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras'))
) with check (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras'))
);
grant select,insert,update,delete on public.co_proveedores to authenticated;
grant usage,select on sequence public.co_proveedores_id_seq to authenticated;

drop policy if exists "Compras consulta solicitudes compra" on public.solicitudes_compra;
create policy "Compras consulta solicitudes compra" on public.solicitudes_compra for select to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras','jefe_almacen','almacen'))
);
drop policy if exists "Compras administra solicitudes compra" on public.solicitudes_compra;
create policy "Compras administra solicitudes compra" on public.solicitudes_compra for all to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras','jefe_almacen'))
) with check (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','compras','jefe_almacen'))
);
grant select,insert,update,delete on public.solicitudes_compra to authenticated;

create table if not exists public.rh_incidencias (
  id bigint generated by default as identity primary key,
  personal_id bigint not null references public.rh_personal(id) on update cascade on delete cascade,
  fecha_inicio date not null,
  fecha_fin date not null,
  tipo text not null check (tipo in ('asistencia','retardo','falta','permiso','vacaciones','incapacidad','home_office','comision')),
  estado text not null default 'registrado' check (estado in ('registrado','pendiente','autorizado','rechazado','cancelado')),
  hora_entrada time,
  hora_salida time,
  minutos_retardo integer not null default 0 check (minutos_retardo >= 0),
  motivo text,
  comprobante_url text,
  autorizado_por uuid references auth.users(id) on delete set null,
  creado_por uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (fecha_fin >= fecha_inicio)
);
create index if not exists rh_incidencias_fecha_idx on public.rh_incidencias(fecha_inicio,fecha_fin);
create index if not exists rh_incidencias_personal_idx on public.rh_incidencias(personal_id);
create index if not exists rh_incidencias_tipo_estado_idx on public.rh_incidencias(tipo,estado);
drop trigger if exists trg_rh_incidencias_actualizar_fecha on public.rh_incidencias;
create trigger trg_rh_incidencias_actualizar_fecha before update on public.rh_incidencias for each row execute function public.rh_co_actualizar_fecha();

alter table public.rh_incidencias enable row level security;
drop policy if exists "RH consulta incidencias" on public.rh_incidencias;
create policy "RH consulta incidencias" on public.rh_incidencias for select to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
drop policy if exists "RH administra incidencias" on public.rh_incidencias;
create policy "RH administra incidencias" on public.rh_incidencias for all to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
) with check (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
grant select,insert,update,delete on public.rh_incidencias to authenticated;
grant usage,select on sequence public.rh_incidencias_id_seq to authenticated;

create table if not exists public.rh_documentos (
  id bigint generated by default as identity primary key,
  personal_id bigint not null references public.rh_personal(id) on update cascade on delete cascade,
  tipo text not null,
  nombre text not null,
  folio text,
  fecha_emision date,
  fecha_vencimiento date,
  estado text not null default 'vigente' check (estado in ('vigente','por_vencer','vencido','pendiente','archivado')),
  archivo_url text,
  notas text,
  creado_por uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (fecha_vencimiento is null or fecha_emision is null or fecha_vencimiento >= fecha_emision)
);
create index if not exists rh_documentos_personal_idx on public.rh_documentos(personal_id);
create index if not exists rh_documentos_vencimiento_idx on public.rh_documentos(fecha_vencimiento);
create index if not exists rh_documentos_estado_idx on public.rh_documentos(estado);
drop trigger if exists trg_rh_documentos_actualizar_fecha on public.rh_documentos;
create trigger trg_rh_documentos_actualizar_fecha before update on public.rh_documentos for each row execute function public.rh_co_actualizar_fecha();

alter table public.rh_documentos enable row level security;
drop policy if exists "RH consulta documentos" on public.rh_documentos;
create policy "RH consulta documentos" on public.rh_documentos for select to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
drop policy if exists "RH administra documentos" on public.rh_documentos;
create policy "RH administra documentos" on public.rh_documentos for all to authenticated using (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
) with check (
  exists(select 1 from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true and p.rol in ('administrador','rh'))
);
grant select,insert,update,delete on public.rh_documentos to authenticated;
grant usage,select on sequence public.rh_documentos_id_seq to authenticated;

create table if not exists public.rh_capacitaciones (
  id bigint generated by default as identity primary key,
  codigo text,
  nombre text not null,
  categoria text,
  proveedor text,
  modalidad text not null default 'presencial' check (modalidad in ('presencial','virtual','mixta')),
  fecha_inicio date not null,
  fecha_fin date not null,
  horas numeric(8,2) not null default 0 check (horas >= 0),
  vigencia_meses integer check (vigencia_meses is null or vigencia_meses >= 0),
  costo numeric(14,2) not null default 0 check (costo >= 0),
  estado text not null default 'programada' check (estado in ('programada','en_curso','finalizada','cancelada')),
  notas text,
  creado_por uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (fecha_fin >= fecha_inicio)
);
create unique index if not exists rh_capacitaciones_codigo_uq on public.rh_capacitaciones(lower(codigo)) where codigo is not null and trim(codigo) <> '';
create index if not exists rh_capacitaciones_fecha_idx on public.rh_capacitaciones(fecha_inicio,fecha_fin);
create index if not exists rh_capacitaciones_estado_idx on public.rh_capacitaciones(estado);
drop trigger if exists trg_rh_capacitaciones_actualizar_fecha on public.rh_capacitaciones;
create trigger trg_rh_capacitaciones_actualizar_fecha before update on public.rh_capacitaciones for each row execute function public.rh_co_actualizar_fecha();

create table if not exists public.rh_capacitacion_participantes (
  id bigint generated by default as identity primary key,
  capacitacion_id bigint not null references public.rh_capacitaciones(id) on update cascade on delete cascade,
  personal_id bigint not null references public.rh_personal(id) on update cascade on delete cascade,
  estado text not null default 'asignado' check (estado in ('asignado','en_curso','aprobado','no_aprobado','cancelado')),
  calificacion numeric(6,2),
  fecha_vencimiento date,
  certificado_url text,
  notas text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(capacitacion_id,personal_id)
);
