create or replace function public.co_marcar_revision_compra()
returns trigger
language plpgsql
as $$
begin
  if new.estado_compras is distinct from old.estado_compras then
    new.revisada_por = auth.uid();
    new.revisada_at = now();
    if new.estado_compras = 'compra_realizada' and new.fecha_compra is null then new.fecha_compra = current_date; end if;
    if new.estado_compras <> 'no_viable' then new.motivo_no_viable = null; end if;
  end if;
  return new;
end;
$$;
