do $$
begin
    if to_regclass('public.ubicaciones_almacen') is null then
        raise exception 'No existe public.ubicaciones_almacen. Instala primero el esquema base del CRM.';
    end if;
    if to_regclass('public.existencias_almacen') is null then
        raise exception 'No existe public.existencias_almacen. Instala primero el esquema base del CRM.';
    end if;
end;
