alter table public.ubicaciones_almacen
    add column if not exists rack_numero smallint,
    add column if not exists zona_numero integer,
    add column if not exists piso_letra text,
    add column if not exists capacidad_consecutivos integer;

update public.ubicaciones_almacen
set capacidad_consecutivos = greatest(1, coalesce(capacidad_consecutivos, columnas, 20))
where capacidad_consecutivos is null
   or capacidad_consecutivos < 1
;

alter table public.ubicaciones_almacen
    alter column capacidad_consecutivos set default 20,
    alter column capacidad_consecutivos set not null;

create or replace function public.crm_sincronizar_ubicacion_estructura_v2()
returns trigger
language plpgsql
set search_path = public
as $$
declare
    v_partes text[];
begin
    new.codigo := upper(btrim(coalesce(new.codigo, '')));
    v_partes := regexp_match(new.codigo, '^(\d{2})-([1-9][0-9]*)-([A-Z])$');

    if v_partes is not null and v_partes[1]::integer between 1 and 20 then
        new.rack_numero := v_partes[1]::integer;
        new.zona_numero := v_partes[2]::integer;
        new.piso_letra := v_partes[3];
        new.filas := 1;
        new.capacidad_consecutivos := greatest(1, coalesce(new.capacidad_consecutivos, new.columnas, 20));
        new.columnas := new.capacidad_consecutivos;
        new.codigo := lpad(new.rack_numero::text, 2, '0') || '-' || new.zona_numero || '-' || new.piso_letra;
    else
        new.rack_numero := null;
        new.zona_numero := null;
        new.piso_letra := null;
        new.capacidad_consecutivos := greatest(1, coalesce(new.capacidad_consecutivos, new.columnas, 20));
    end if;

    return new;
end;
$$;

drop trigger if exists trg_ubicaciones_almacen_v2 on public.ubicaciones_almacen;
create trigger trg_ubicaciones_almacen_v2
before insert or update of codigo, columnas, capacidad_consecutivos
on public.ubicaciones_almacen
for each row
execute function public.crm_sincronizar_ubicacion_estructura_v2();

update public.ubicaciones_almacen
set codigo = codigo,
    capacidad_consecutivos = greatest(1, coalesce(capacidad_consecutivos, columnas, 20));

alter table public.ubicaciones_almacen
    drop constraint if exists ubicaciones_almacen_rack_v2_check,
    drop constraint if exists ubicaciones_almacen_zona_v2_check,
    drop constraint if exists ubicaciones_almacen_piso_v2_check,
    drop constraint if exists ubicaciones_almacen_capacidad_v2_check;

alter table public.ubicaciones_almacen
    add constraint ubicaciones_almacen_rack_v2_check check (rack_numero is null or rack_numero between 1 and 20),
    add constraint ubicaciones_almacen_zona_v2_check check (zona_numero is null or zona_numero >= 1),
    add constraint ubicaciones_almacen_piso_v2_check check (piso_letra is null or piso_letra ~ '^[A-Z]$'),
    add constraint ubicaciones_almacen_capacidad_v2_check check (capacidad_consecutivos >= 1);

create or replace function public.crm_ubicacion_material_v2_valida(p_ubicacion text)
returns boolean
language sql
immutable
set search_path = public
as $$
    select p_ubicacion is null
        or btrim(p_ubicacion) = ''
        or upper(btrim(p_ubicacion)) ~ '^(0[1-9]|1[0-9]|20)-[1-9][0-9]*-[A-Z][1-9][0-9]*$';
$$;

create or replace view public.vw_ubicaciones_estructura_pendientes_v2 as
select
    u.id,
    u.almacen_id,
    u.nombre,
    u.codigo,
    u.estado,
    case
        when coalesce(btrim(u.codigo), '') = '' then 'Sin código base'
        when upper(btrim(u.codigo)) !~ '^(0[1-9]|1[0-9]|20)-[1-9][0-9]*-[A-Z]$' then 'Formato anterior o inválido'
        else 'Revisar'
    end as motivo
from public.ubicaciones_almacen u
where coalesce(btrim(u.codigo), '') = ''
   or upper(btrim(u.codigo)) !~ '^(0[1-9]|1[0-9]|20)-[1-9][0-9]*-[A-Z]$';

create or replace view public.vw_materiales_ubicacion_pendiente_v2 as
select
    e.id,
    e.material_codigo,
    e.almacen_id,
    e.ubicacion,
    case
        when coalesce(btrim(e.ubicacion), '') = '' then 'Sin ubicación específica'
        when not public.crm_ubicacion_material_v2_valida(e.ubicacion) then 'Formato anterior o inválido'
        else 'Revisar estructura o capacidad'
    end as motivo
from public.existencias_almacen e
where coalesce(btrim(e.ubicacion), '') = ''
   or not public.crm_ubicacion_material_v2_valida(e.ubicacion);

grant select on public.vw_ubicaciones_estructura_pendientes_v2, public.vw_materiales_ubicacion_pendiente_v2 to authenticated;

commit;

select 'OK' as estado, 'Ubicaciones V2 instaladas' as detalle;


begin;

do $$
begin
    if to_regclass('public.perfiles_usuario') is null then
        raise exception 'No existe public.perfiles_usuario. Instala primero el esquema base del CRM.';
    end if;
end;
$$;

do $$
declare
    v_constraint record;
begin
    for v_constraint in
        select conname
        from pg_constraint
        where conrelid = 'public.perfiles_usuario'::regclass
          and contype = 'c'
          and pg_get_constraintdef(oid) ilike '%rol%'
    loop
        execute format('alter table public.perfiles_usuario drop constraint %I', v_constraint.conname);
    end loop;
end;
$$;
update public.perfiles_usuario
set rol = case
    when lower(btrim(coalesce(rol,''))) in ('administrador','admin','administracion','administración') then 'administrador'
    when lower(btrim(coalesce(rol,''))) in ('jefe_almacen','jefe almacen','jefe de almacen','jefe de almacén','responsable almacen','responsable de almacen') then 'jefe_almacen'
    when lower(btrim(coalesce(rol,''))) in ('almacen','almacén','almacenista','bodega','bodeguero') then 'almacen'
    when lower(btrim(coalesce(rol,''))) in ('compras','comprador','compradora','abastecimiento') then 'compras'
    when lower(btrim(coalesce(rol,''))) in ('proyectos','proyecto','project manager','lider de proyecto','líder de proyecto') then 'proyectos'
    when lower(btrim(coalesce(rol,''))) in ('planeacion','planeación','planeador','planeadora') then 'planeacion'
    when lower(btrim(coalesce(rol,''))) in ('coordinacion','coordinación','coordinador','coordinadora') then 'coordinacion'
    when lower(btrim(coalesce(rol,''))) in ('logistica','logística','logistico','logístico','logistica vehicular','logística vehicular') then 'logistica'
    when lower(btrim(coalesce(rol,''))) in ('recepcion','recepción','recepcionista','front desk','entrada principal','caseta','atencion a visitantes','atención a visitantes') then 'recepcion'
    when lower(btrim(coalesce(rol,''))) in ('rh','rrhh','recursos humanos','capital humano') then 'rh'
    when lower(btrim(coalesce(rol,''))) in ('finanzas','financiero','financiera','contabilidad') then 'finanzas'
    when lower(btrim(coalesce(rol,''))) in ('gerente_general','gerente general','gg','gerencia general','gerencia','direccion','dirección','director','directora') then 'gerente_general'
    when lower(btrim(coalesce(rol,''))) in ('subgerente','subgerencia','sg','sub gerente') then 'subgerente'
    when lower(btrim(coalesce(rol,''))) in ('tsi','sistemas','tecnologia','tecnología','tecnologias de la informacion','tecnologías de la información') then 'tsi'
    when lower(btrim(coalesce(rol,''))) in ('sky_demo','sky demo','sky','demo') then 'sky_demo'
    when lower(btrim(coalesce(rol,''))) in ('consulta','consultas','lector','lectura','solo lectura') then 'consulta'
    else 'consulta'
end;

alter table public.perfiles_usuario
    add constraint perfiles_usuario_rol_check
    check (lower(btrim(rol)) in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','gerente_general','subgerente','tsi','sky_demo','consulta'));

create or replace function public.crm_usuario_tiene_rol(p_roles text[])
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists(
        select 1
        from public.perfiles_usuario p
        where p.id = auth.uid()
          and p.activo = true
          and lower(btrim(p.rol)) = any(select lower(btrim(x)) from unnest(p_roles) as x)
    );
$$;

revoke all on function public.crm_usuario_tiene_rol(text[]) from public, anon;
grant execute on function public.crm_usuario_tiene_rol(text[]) to authenticated, service_role;

create or replace function public.crm_asignar_rol_por_correo(
    p_correo text,
    p_rol text,
    p_activo boolean default true
)
returns public.perfiles_usuario
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_usuario_id uuid;
    v_perfil public.perfiles_usuario%rowtype;
    v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), '');
begin
    p_rol:=lower(btrim(p_rol));
    if p_rol not in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','gerente_general','subgerente','tsi','sky_demo','consulta') then
        raise exception 'Rol no válido: %', p_rol;
    end if;

    if auth.uid() is not null then
        if not public.crm_usuario_tiene_rol(array['administrador']) then
            raise exception using errcode = '42501', message = 'Solo un administrador activo puede asignar roles.';
        end if;
    elsif session_user not in ('postgres','supabase_admin') and v_jwt_role <> 'service_role' then
        raise exception using errcode = '42501', message = 'La asignación de roles requiere administrador o service_role.';
    end if;

    select id
    into v_usuario_id
    from auth.users
    where lower(email) = lower(btrim(p_correo))
    limit 1;

    if v_usuario_id is null then
        raise exception 'No existe un usuario con el correo %', p_correo;
    end if;

    insert into public.perfiles_usuario(id, nombre, rol, activo)
    select
        u.id,
        coalesce(nullif(u.raw_user_meta_data->>'nombre', ''), split_part(u.email, '@', 1)),
        p_rol,
        p_activo
    from auth.users u
    where u.id = v_usuario_id
    on conflict(id) do update
    set rol = excluded.rol,
        activo = excluded.activo,
        updated_at = now()
    returning * into v_perfil;

    return v_perfil;
end;
$$;

revoke all on function public.crm_asignar_rol_por_correo(text,text,boolean) from public, anon;
grant execute on function public.crm_asignar_rol_por_correo(text,text,boolean) to authenticated, service_role;

alter table public.perfiles_usuario enable row level security;

do $$
declare
    v_policy record;
begin
    for v_policy in
        select policyname
        from pg_policies
        where schemaname = 'public'
          and tablename = 'perfiles_usuario'
    loop
        execute format('drop policy if exists %I on public.perfiles_usuario', v_policy.policyname);
    end loop;
end;
$$;

