create policy perfiles_usuario_administracion
on public.perfiles_usuario
for update
to authenticated
using (public.crm_usuario_tiene_rol(array['administrador']))
with check (public.crm_usuario_tiene_rol(array['administrador']));

grant select on public.perfiles_usuario to authenticated;
revoke insert, delete on public.perfiles_usuario from anon, authenticated;

commit;

