begin;

create or replace function public.crm_usuario_tiene_rol(p_roles text[])
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists(
        select 1
        from public.perfiles_usuario p
        where p.id = auth.uid()
          and p.activo = true
          and lower(btrim(p.rol)) = any(select lower(btrim(x)) from unnest(p_roles) as x)
    );
$$;

revoke all on function public.crm_usuario_tiene_rol(text[]) from public, anon;
grant execute on function public.crm_usuario_tiene_rol(text[]) to authenticated, service_role;

create or replace function public.crm_aplicar_rls_por_roles(
    p_tabla text,
    p_roles_lectura text[],
    p_roles_escritura text[] default array[]::text[]
)
returns void
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
    v_policy record;
    v_regclass regclass;
begin
    v_regclass := to_regclass('public.' || quote_ident(p_tabla));
    if v_regclass is null then
        raise notice 'Se omite %. La tabla no existe.', p_tabla;
        return;
    end if;

    execute format('alter table public.%I enable row level security', p_tabla);

    for v_policy in
        select policyname
        from pg_policies
        where schemaname = 'public'
          and tablename = p_tabla
    loop
        execute format('drop policy if exists %I on public.%I', v_policy.policyname, p_tabla);
    end loop;

    execute format(
        'create policy crm_lectura on public.%I for select to authenticated using (public.crm_usuario_tiene_rol(%L::text[]))',
        p_tabla,
        p_roles_lectura
    );

    execute format('revoke all on public.%I from anon', p_tabla);
    execute format('grant select on public.%I to authenticated', p_tabla);

    if coalesce(array_length(p_roles_escritura, 1), 0) > 0 then
        execute format(
            'create policy crm_escritura on public.%I for all to authenticated using (public.crm_usuario_tiene_rol(%L::text[])) with check (public.crm_usuario_tiene_rol(%L::text[]))',
            p_tabla,
            p_roles_escritura,
            p_roles_escritura
        );
        execute format('grant insert, update, delete on public.%I to authenticated', p_tabla);
    else
        execute format('revoke insert, update, delete on public.%I from authenticated', p_tabla);
    end if;
end;
$$;

