create or replace function public.crm_guardar_vehiculo(
    p_id bigint default null,
    p_datos jsonb default '{}'::jsonb
)
returns public.vehiculos
language plpgsql
security definer
set search_path = public
as $$
declare
    v_result public.vehiculos%rowtype;
    v_numero text;
    v_marca text;
    v_modelo text;
begin
    if auth.uid() is not null and not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen','almacen','rh']) then
        raise exception using errcode='42501', message='Tu perfil no tiene permiso para guardar o editar vehículos.';
    end if;

    v_numero := btrim(coalesce(p_datos->>'numero_economico',''));
    v_marca := btrim(coalesce(p_datos->>'marca',''));
    v_modelo := btrim(coalesce(p_datos->>'modelo',''));

    if v_numero='' then raise exception 'El nombre del vehículo es obligatorio.'; end if;
    if v_marca='' or v_modelo='' then raise exception 'Marca y modelo son obligatorios.'; end if;

    if coalesce(p_id,0)=0 then
        insert into public.vehiculos(
            numero_economico,placas,vin,marca,modelo,anio,tipo,color,combustible,transmision,
            capacidad_carga,capacidad_personas,distribucion_asientos,kilometraje,propiedad,estado,
            almacen_base_id,proyecto,asignado_a,responsable,aseguradora,poliza_seguro,vigencia_seguro,
            tarjeta_circulacion,vigencia_tarjeta,proxima_verificacion,fecha_adquisicion,costo_adquisicion,
            imagen_url,notas,activo,created_at,updated_at
        ) values(
            v_numero,nullif(upper(btrim(coalesce(p_datos->>'placas',''))),''),nullif(upper(btrim(coalesce(p_datos->>'vin',''))),''),
            v_marca,v_modelo,nullif(p_datos->>'anio','')::integer,coalesce(nullif(p_datos->>'tipo',''),'pickup'),
            nullif(p_datos->>'color',''),nullif(p_datos->>'combustible',''),nullif(p_datos->>'transmision',''),
            greatest(0,coalesce(nullif(p_datos->>'capacidad_carga','')::numeric,0)),
            greatest(0,coalesce(nullif(p_datos->>'capacidad_personas','')::integer,0)),
            coalesce(p_datos->'distribucion_asientos','{"version":1,"filas":[]}'::jsonb),
            greatest(0,coalesce(nullif(p_datos->>'kilometraje','')::numeric,0)),coalesce(nullif(p_datos->>'propiedad',''),'empresa'),
            coalesce(nullif(p_datos->>'estado',''),'disponible'),nullif(p_datos->>'almacen_base_id','')::bigint,
            nullif(p_datos->>'proyecto',''),nullif(p_datos->>'asignado_a',''),nullif(p_datos->>'responsable',''),
            nullif(p_datos->>'aseguradora',''),nullif(p_datos->>'poliza_seguro',''),nullif(p_datos->>'vigencia_seguro','')::date,
            nullif(p_datos->>'tarjeta_circulacion',''),nullif(p_datos->>'vigencia_tarjeta','')::date,
            nullif(p_datos->>'proxima_verificacion','')::date,nullif(p_datos->>'fecha_adquisicion','')::date,
            greatest(0,coalesce(nullif(p_datos->>'costo_adquisicion','')::numeric,0)),nullif(p_datos->>'imagen_url',''),
            nullif(p_datos->>'notas',''),coalesce(nullif(p_datos->>'activo','')::boolean,true),now(),now()
        ) returning * into v_result;
    else
        update public.vehiculos set
            numero_economico=v_numero,
            placas=nullif(upper(btrim(coalesce(p_datos->>'placas',''))),''),
            vin=nullif(upper(btrim(coalesce(p_datos->>'vin',''))),''),
            marca=v_marca,
            modelo=v_modelo,
            anio=nullif(p_datos->>'anio','')::integer,
            tipo=coalesce(nullif(p_datos->>'tipo',''),'pickup'),
            color=nullif(p_datos->>'color',''),
            combustible=nullif(p_datos->>'combustible',''),
            transmision=nullif(p_datos->>'transmision',''),
            capacidad_carga=greatest(0,coalesce(nullif(p_datos->>'capacidad_carga','')::numeric,0)),
            capacidad_personas=greatest(0,coalesce(nullif(p_datos->>'capacidad_personas','')::integer,0)),
            distribucion_asientos=coalesce(p_datos->'distribucion_asientos','{"version":1,"filas":[]}'::jsonb),
            kilometraje=greatest(0,coalesce(nullif(p_datos->>'kilometraje','')::numeric,0)),
            propiedad=coalesce(nullif(p_datos->>'propiedad',''),'empresa'),
            estado=coalesce(nullif(p_datos->>'estado',''),'disponible'),
            almacen_base_id=nullif(p_datos->>'almacen_base_id','')::bigint,
            proyecto=nullif(p_datos->>'proyecto',''),
            asignado_a=nullif(p_datos->>'asignado_a',''),
            responsable=nullif(p_datos->>'responsable',''),
            aseguradora=nullif(p_datos->>'aseguradora',''),
            poliza_seguro=nullif(p_datos->>'poliza_seguro',''),
            vigencia_seguro=nullif(p_datos->>'vigencia_seguro','')::date,
            tarjeta_circulacion=nullif(p_datos->>'tarjeta_circulacion',''),
            vigencia_tarjeta=nullif(p_datos->>'vigencia_tarjeta','')::date,
            proxima_verificacion=nullif(p_datos->>'proxima_verificacion','')::date,
            fecha_adquisicion=nullif(p_datos->>'fecha_adquisicion','')::date,
            costo_adquisicion=greatest(0,coalesce(nullif(p_datos->>'costo_adquisicion','')::numeric,0)),
            imagen_url=nullif(p_datos->>'imagen_url',''),
            notas=nullif(p_datos->>'notas',''),
            activo=coalesce(nullif(p_datos->>'activo','')::boolean,activo),
            updated_at=now()
        where id=p_id
        returning * into v_result;

        if not found then
            raise exception 'No existe el vehículo con ID %.',p_id;
        end if;
    end if;

    return v_result;
exception
    when unique_violation then
        raise exception using errcode='23505', message='El número económico, las placas o el VIN ya están registrados.';
end;
$$;

revoke all on function public.crm_guardar_vehiculo(bigint,jsonb) from public,anon;
grant execute on function public.crm_guardar_vehiculo(bigint,jsonb) to authenticated,service_role;
grant select,insert,update on public.vehiculos to authenticated;
grant usage,select on all sequences in schema public to authenticated;
notify pgrst, 'reload schema';

commit;


