create or replace function public.crm_eliminar_movimiento_prueba(
    p_request_id text default null,
    p_movimiento_id bigint default null
) returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_request text:=btrim(coalesce(p_request_id,''));
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if v_request='' and coalesce(p_movimiento_id,0)<=0 then
        raise exception 'Falta identificar el movimiento.';
    end if;

    if to_regclass('public.ubicaciones_pendientes') is not null and v_request<>'' then
        execute 'delete from public.ubicaciones_pendientes where request_id=$1' using v_request;
    end if;

    if v_request<>'' then
        delete from public.movimientos where request_id=v_request;
    else
        delete from public.movimientos where id=p_movimiento_id;
    end if;
    get diagnostics v_count=row_count;

    if v_count=0 then
        raise exception 'No se encontró el movimiento solicitado.';
    end if;

    return jsonb_build_object(
        'ok',true,
        'eliminados',v_count,
        'requestId',nullif(v_request,''),
        'advertencia','Se eliminó el historial. Las existencias físicas no se recalculan automáticamente.'
    );
end;
$$;

revoke all on function public.crm_eliminar_movimiento_prueba(text,bigint) from public,anon;
grant execute on function public.crm_eliminar_movimiento_prueba(text,bigint) to authenticated;

create or replace function public.crm_eliminar_solicitud_material_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_project text;
    v_code text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    select proyecto_numero,material_codigo into v_project,v_code
    from public.proyecto_materiales where id=p_id;
    if not found then raise exception 'No se encontró la solicitud de material.'; end if;

    if to_regclass('public.reajustes_solicitud_material') is not null then
        execute 'delete from public.reajustes_solicitud_material where proyecto_numero=$1 and material_codigo=$2' using v_project,v_code;
    end if;
    if to_regclass('public.notificaciones_sistema') is not null then
        execute 'delete from public.notificaciones_sistema where proyecto_numero=$1 and material_codigo=$2' using v_project,v_code;
    end if;

    delete from public.proyecto_materiales where id=p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'proyecto',v_project,'codigo',v_code);
end;
$$;

revoke all on function public.crm_eliminar_solicitud_material_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_solicitud_material_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_reajuste_material_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_project text;
    v_code text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.reajustes_solicitud_material') is null then
        raise exception 'No existe el módulo de reajustes.';
    end if;
    execute 'select proyecto_numero,material_codigo from public.reajustes_solicitud_material where id=$1'
        into v_project,v_code using p_id;
    if v_project is null then raise exception 'No se encontró el reajuste.'; end if;
    if to_regclass('public.notificaciones_sistema') is not null then
        execute 'delete from public.notificaciones_sistema where entidad_id=$1 and tipo=''reajuste_solicitud_material''' using p_id;
    end if;
    execute 'delete from public.reajustes_solicitud_material where id=$1' using p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'proyecto',v_project,'codigo',v_code);
end;
$$;

revoke all on function public.crm_eliminar_reajuste_material_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_reajuste_material_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_historial_herramienta_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.herramientas_historial') is null then
        raise exception 'No existe el historial de herramientas.';
    end if;
    execute 'delete from public.herramientas_historial where id=$1' using p_id;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se encontró el evento de historial.'; end if;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id);
end;
$$;

revoke all on function public.crm_eliminar_historial_herramienta_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_historial_herramienta_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_herramienta_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_units bigint[]:=array[]::bigint[];
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if not exists(select 1 from public.herramientas_catalogo where id=p_id) then
        raise exception 'No se encontró la herramienta.';
    end if;
    select coalesce(array_agg(id),array[]::bigint[]) into v_units
    from public.herramientas_unidades where herramienta_id=p_id;

    if to_regclass('public.herramientas_historial') is not null then
        execute 'delete from public.herramientas_historial where herramienta_id=$1 or unidad_id=any($2)' using p_id,v_units;
    end if;
    if to_regclass('public.herramientas_asignaciones') is not null and cardinality(v_units)>0 then
        execute 'delete from public.herramientas_asignaciones where unidad_id=any($1)' using v_units;
    end if;
    if to_regclass('public.proyecto_herramientas') is not null then
        execute 'delete from public.proyecto_herramientas where herramienta_id=$1' using p_id;
    end if;
    delete from public.herramientas_unidades where herramienta_id=p_id;
    delete from public.herramientas_catalogo where id=p_id;
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id,'unidades_eliminadas',cardinality(v_units));
end;
$$;

revoke all on function public.crm_eliminar_herramienta_prueba(bigint) from public,anon;
grant execute on function public.crm_eliminar_herramienta_prueba(bigint) to authenticated;

create or replace function public.crm_eliminar_proyecto_prueba(p_proyecto text)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_project text:=btrim(coalesce(p_proyecto,''));
    v_moves integer:=0;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if v_project='' then raise exception 'Falta el proyecto.'; end if;
    select count(*) into v_moves from public.movimientos where proyecto=v_project;
    if exists(
        select 1 from information_schema.columns
        where table_schema='public' and table_name='movimientos' and column_name='proyecto_destino'
    ) then
        execute 'select $1 + count(*) from public.movimientos where proyecto_destino=$2' into v_moves using v_moves,v_project;
    end if;
    if v_moves>0 then
        raise exception 'El proyecto todavía tiene % movimiento(s). Elimina primero esos movimientos desde Historial de movimientos.',v_moves;
    end if;

    if to_regclass('public.reajustes_solicitud_material') is not null then
        execute 'delete from public.reajustes_solicitud_material where proyecto_numero=$1' using v_project;
    end if;
    if to_regclass('public.notificaciones_sistema') is not null then
        execute 'delete from public.notificaciones_sistema where proyecto_numero=$1' using v_project;
    end if;
    if to_regclass('public.proyecto_herramientas') is not null then
        execute 'delete from public.proyecto_herramientas where proyecto_numero=$1' using v_project;
    end if;
    if to_regclass('public.existencias_proyecto_almacen') is not null then
        execute 'delete from public.existencias_proyecto_almacen where proyecto_numero=$1' using v_project;
    end if;
    if to_regclass('public.proyecto_materiales_no_listados') is not null then
        execute 'delete from public.proyecto_materiales_no_listados where proyecto_numero=$1' using v_project;
    end if;
    delete from public.proyecto_materiales where proyecto_numero=v_project;
    delete from public.proyectos where numero_proyecto=v_project;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se encontró el proyecto.'; end if;
    return jsonb_build_object('ok',true,'eliminados',v_count,'proyecto',v_project);
end;
$$;

revoke all on function public.crm_eliminar_proyecto_prueba(text) from public,anon;
grant execute on function public.crm_eliminar_proyecto_prueba(text) to authenticated;

create or replace function public.crm_eliminar_orden_compra_prueba(p_ids bigint[])
returns jsonb
language plpgsql
security definer
set search_path=public,storage
as $$
declare
    v_paths text[]:=array[]::text[];
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if p_ids is null or cardinality(p_ids)=0 then raise exception 'Selecciona una orden de compra.'; end if;
    select coalesce(array_agg(distinct pdf_path) filter(where coalesce(btrim(pdf_path),'')<>''),array[]::text[])
      into v_paths from public.solicitudes_compra where id=any(p_ids);
    delete from public.solicitudes_compra where id=any(p_ids);
    get diagnostics v_count=row_count;
    return jsonb_build_object('ok',true,'eliminados',v_count,'pdf_paths',to_jsonb(v_paths));
end;
$$;

revoke all on function public.crm_eliminar_orden_compra_prueba(bigint[]) from public,anon;
grant execute on function public.crm_eliminar_orden_compra_prueba(bigint[]) to authenticated;

create or replace function public.crm_eliminar_vehiculo_prueba(p_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','jefe_almacen']) then
        raise exception 'Solo Administrador o Jefe de almacén puede eliminar registros de prueba.';
    end if;
    if to_regclass('public.vehiculos_gastos') is not null then execute 'delete from public.vehiculos_gastos where vehiculo_id=$1' using p_id; end if;
    if to_regclass('public.vehiculos_viajes') is not null then execute 'delete from public.vehiculos_viajes where vehiculo_id=$1' using p_id; end if;
    delete from public.vehiculos where id=p_id;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se encontró el vehículo.'; end if;
    return jsonb_build_object('ok',true,'eliminados',v_count,'id',p_id);
end;
$$;

revoke all on function public.crm_eliminar_vehiculo_prueba(bigint) from public,anon;
