    estado text not null default 'solicitada' check (estado in ('solicitada','en_revision','cotizando','comparada','aprobada','rechazada','cerrada')),
    prioridad text not null default 'normal' check (prioridad in ('critica','urgente','alta','normal','baja','programada')),
    fecha_requerida date,
    solicitado_por text,
    referencia text,
    notas text,
    revisada_por uuid references auth.users(id) on delete set null,
    revisada_at timestamptz,
    aprobada_por uuid references auth.users(id) on delete set null,
    aprobada_at timestamptz,
