create or replace function public.co_marcar_revision_cotizacion()
returns trigger
language plpgsql
set search_path=public
as $$
begin
    if new.estado is distinct from old.estado and new.estado in ('en_revision','cotizando','comparada','aprobada') then
        new.revisada_por := coalesce(new.revisada_por,auth.uid());
        new.revisada_at := coalesce(new.revisada_at,now());
    end if;
    return new;
end;
$$;
drop trigger if exists trg_co_cotizaciones_revision on public.co_cotizaciones;
create trigger trg_co_cotizaciones_revision before update of estado on public.co_cotizaciones for each row execute function public.co_marcar_revision_cotizacion();

alter table public.co_cotizaciones
    drop constraint if exists co_cotizaciones_prioridad_check;
alter table public.co_cotizaciones
    add constraint co_cotizaciones_prioridad_check
    check (prioridad in ('critica','urgente','alta','normal','baja','programada'));

create or replace function public.crm_actualizar_niveles_stock_lote(p_items jsonb)
returns integer
language plpgsql
set search_path=public
as $$
declare
    v_updated integer := 0;
begin
    if p_items is null or jsonb_typeof(p_items) <> 'array' then
        return 0;
    end if;

    with payload as (
        select
            nullif(btrim(x.codigo),'') as material_codigo,
            x.almacen_id,
            greatest(coalesce(x.stock_minimo,0),0) as stock_minimo,
            greatest(coalesce(x.stock_medio,0),0) as stock_medio,
            greatest(coalesce(x.stock_maximo,0),0) as stock_maximo
        from jsonb_to_recordset(p_items) as x(
            codigo text,
            almacen_id bigint,
            stock_minimo numeric,
            stock_medio numeric,
            stock_maximo numeric
        )
        where nullif(btrim(x.codigo),'') is not null
          and x.almacen_id is not null
          and x.almacen_id > 0
    ),
    normalized as (
        select
            material_codigo,
            almacen_id,
            stock_minimo,
            least(greatest(stock_medio,stock_minimo),greatest(stock_maximo,stock_minimo)) as stock_medio,
            greatest(stock_maximo,stock_minimo) as stock_maximo
        from payload
    )
    update public.existencias_almacen e
       set stock_minimo = n.stock_minimo,
           stock_medio = n.stock_medio,
           stock_maximo = n.stock_maximo,
           updated_at = now()
      from normalized n
     where e.material_codigo = n.material_codigo
       and e.almacen_id = n.almacen_id;

    get diagnostics v_updated = row_count;
    return v_updated;
end;
$$;
grant execute on function public.crm_actualizar_niveles_stock_lote(jsonb) to authenticated;

create table if not exists public.co_cotizacion_items (
    id bigint generated by default as identity primary key,
    cotizacion_id uuid not null references public.co_cotizaciones(id) on update cascade on delete cascade,
    material_codigo text not null references public.materiales(codigo) on update cascade on delete restrict,
    descripcion text not null,
    marca text,
    unidad text,
    cantidad numeric(16,4) not null check (cantidad > 0),
    almacen_id bigint references public.almacenes(id) on update cascade on delete set null,
    almacen_nombre text,
    existencia_actual numeric(16,4) not null default 0,
    stock_minimo numeric(16,4) not null default 0,
    stock_medio numeric(16,4) not null default 0,
    stock_maximo numeric(16,4) not null default 0,
    estado text not null default 'pendiente' check (estado in ('pendiente','con_opciones','seleccionado','cerrado')),
    proveedor_seleccionado_id bigint references public.co_proveedores(id) on update cascade on delete set null,
    oferta_seleccionada_id bigint,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(cotizacion_id,material_codigo,almacen_id)
);

create index if not exists co_cotizacion_items_cotizacion_idx on public.co_cotizacion_items(cotizacion_id);
create index if not exists co_cotizacion_items_material_idx on public.co_cotizacion_items(material_codigo);
drop trigger if exists trg_co_cotizacion_items_fecha on public.co_cotizacion_items;
create trigger trg_co_cotizacion_items_fecha before update on public.co_cotizacion_items for each row execute function public.co_actualizar_fecha();

create or replace function public.crm_crear_cotizacion(
    p_origen text,
    p_prioridad text,
    p_fecha_requerida date,
    p_solicitado_por text,
    p_referencia text,
    p_notas text,
    p_items jsonb
)
returns jsonb
language plpgsql
set search_path=public
as $$
declare
    v_id uuid;
    v_folio text;
    v_count integer := 0;
    v_priority text;
begin
    if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items)=0 then
        raise exception 'Selecciona al menos un material para cotizar.';
    end if;

    v_priority := case lower(coalesce(p_prioridad,'normal'))
        when 'critica' then 'critica'
        when 'urgente' then 'urgente'
        when 'alta' then 'alta'
        when 'baja' then 'baja'
        when 'programada' then 'programada'
        else 'normal'
    end;

    v_folio := 'COT-' || to_char(clock_timestamp(),'YYYYMMDD-HH24MISS') || '-' || upper(substr(md5(random()::text),1,3));

    insert into public.co_cotizaciones(
        folio,origen,estado,prioridad,fecha_requerida,solicitado_por,referencia,notas,updated_at
    )
    values(
        v_folio,
        case when p_origen in ('bajo_minimo','manual','proyecto','requisicion') then p_origen else 'bajo_minimo' end,
        'solicitada',
        v_priority,
        p_fecha_requerida,
        nullif(btrim(p_solicitado_por),''),
        nullif(btrim(p_referencia),''),
        nullif(btrim(p_notas),''),
        now()
    )
    returning id into v_id;

    insert into public.co_cotizacion_items(
        cotizacion_id,material_codigo,descripcion,marca,unidad,cantidad,
        almacen_id,almacen_nombre,existencia_actual,stock_minimo,stock_medio,stock_maximo,
        estado,updated_at
    )
    select
        v_id,
        nullif(btrim(x.material_codigo),''),
        nullif(btrim(x.descripcion),''),
        nullif(btrim(x.marca),''),
        nullif(btrim(x.unidad),''),
        greatest(coalesce(x.cantidad,0),0),
        case when coalesce(x.almacen_id,0)>0 then x.almacen_id else null end,
        nullif(btrim(x.almacen_nombre),''),
        greatest(coalesce(x.existencia_actual,0),0),
        greatest(coalesce(x.stock_minimo,0),0),
        greatest(coalesce(x.stock_medio,0),0),
        greatest(coalesce(x.stock_maximo,0),0),
        'pendiente',
        now()
    from jsonb_to_recordset(p_items) as x(
        material_codigo text,
        descripcion text,
        marca text,
        unidad text,
        cantidad numeric,
        almacen_id bigint,
        almacen_nombre text,
        existencia_actual numeric,
        stock_minimo numeric,
        stock_medio numeric,
        stock_maximo numeric
    )
    where nullif(btrim(x.material_codigo),'') is not null
      and nullif(btrim(x.descripcion),'') is not null
      and coalesce(x.cantidad,0) > 0;

    get diagnostics v_count = row_count;
    if v_count = 0 then
        raise exception 'No hay materiales válidos para cotizar.';
    end if;

    return jsonb_build_object(
        'id',v_id,
        'folio',v_folio,
        'estado','solicitada',
        'prioridad',v_priority,
        'items',v_count
    );
end;
$$;
grant execute on function public.crm_crear_cotizacion(text,text,date,text,text,text,jsonb) to authenticated;

create table if not exists public.co_cotizacion_ofertas (
    id bigint generated by default as identity primary key,
    cotizacion_item_id bigint not null references public.co_cotizacion_items(id) on update cascade on delete cascade,
    proveedor_id bigint references public.co_proveedores(id) on update cascade on delete set null,
    proveedor_temporal_nombre text,
    proveedor_temporal_contacto text,
    proveedor_temporal_email text,
    proveedor_temporal_telefono text,
    precio_unitario numeric(16,4) not null default 0 check (precio_unitario >= 0),
    moneda text not null default 'MXN' check (moneda in ('MXN','USD','EUR')),
    plazo_entrega_dias integer not null default 0 check (plazo_entrega_dias >= 0),
    vigencia_hasta date,
    cantidad_minima numeric(16,4) not null default 1 check (cantidad_minima > 0),
    observaciones text,
    origen text not null default 'cotizacion' check (origen in ('catalogo','cotizacion','manual')),
    estado text not null default 'pendiente' check (estado in ('pendiente','recibida','seleccionada','descartada')),
    fecha_solicitud timestamptz,
    fecha_respuesta timestamptz,
    solicitud_proveedor_id uuid references public.co_solicitudes_proveedor(id) on update cascade on delete set null,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    check (proveedor_id is not null or coalesce(btrim(proveedor_temporal_nombre),'') <> '')
);

