returns trigger
language plpgsql
set search_path=public
as $$
begin
    if lower(btrim(coalesce(new.categoria,''))) in ('cable','cables') then
        new.unidad:='METRO';
    else
        new.tipo_cable:=null;
        new.tamano_mm2:=null;
    end if;
    return new;
end;
$$;

drop trigger if exists trg_material_campos_cable on public.materiales;
