stable
security definer
set search_path=public
as $$
    select auth.uid() is not null and exists(
        select 1 from public.perfiles_usuario p
        where p.id=auth.uid() and p.activo=true and lower(coalesce(p.rol,'')) in ('administrador','jefe_almacen','almacen')
