grant execute on function public.crm_paquetes_es_administrador() to authenticated;
grant execute on function public.crm_paquetes_es_operador_almacen() to authenticated;

create or replace function public.crm_listar_paquetes_materiales(p_incluir_inactivos boolean default false)
returns jsonb
language plpgsql
stable
security definer
set search_path=public
as $$
declare
    v_admin boolean:=public.crm_paquetes_es_administrador();
    v_rol text:='consulta';
    v_result jsonb;
begin
    if not public.crm_paquetes_usuario_activo() then
        raise exception using errcode='42501',message='Tu perfil no puede consultar paquetes de materiales.';
    end if;
    select lower(coalesce(p.rol,'consulta')) into v_rol from public.perfiles_usuario p where p.id=auth.uid();
    v_rol:=coalesce(nullif(v_rol,''),'consulta');
    select coalesce(jsonb_agg(obj order by (obj->>'orden')::integer,obj->>'nombre'),'[]'::jsonb)
    into v_result
    from (
        select jsonb_build_object(
            'id',p.id,
            'nombre',p.nombre,
            'descripcion',coalesce(p.descripcion,''),
            'categoria',coalesce(nullif(p.categoria,''),'General'),
            'activo',p.activo,
            'orden',p.orden,
            'createdAt',p.created_at,
            'updatedAt',p.updated_at,
            'items',coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id',i.id,
                    'codigo',i.material_codigo,
                    'descripcion',coalesce(m.descripcion,i.material_codigo),
                    'unidad',coalesce(nullif(m.unidad,''),'pieza'),
                    'marca',coalesce(m.marca,''),
                    'codigoMarca',coalesce(m.codigo_marca,''),
                    'cantidad',i.cantidad,
                    'notas',coalesce(i.notas,''),
                    'stockTotal',coalesce((select sum(e.stock) from public.existencias_almacen e where e.material_codigo=i.material_codigo),0)
                ) order by coalesce(m.descripcion,i.material_codigo),i.material_codigo)
                from public.crm_paquetes_materiales_items i
                left join public.materiales m on m.codigo=i.material_codigo
                where i.paquete_id=p.id
            ),'[]'::jsonb)
        ) obj
        from public.crm_paquetes_materiales p
        where ((v_admin and coalesce(p_incluir_inactivos,false))
           or (p.activo=true and exists(select 1 from public.crm_paquetes_materiales_items i where i.paquete_id=p.id)))
          and (v_rol<>'tsi' or not exists(
              select 1
              from public.crm_paquetes_materiales_items i
              left join public.materiales m on m.codigo=i.material_codigo
              where i.paquete_id=p.id and upper(btrim(coalesce(m.categoria,'')))<>'EPP'
          ))
    ) q;
    return coalesce(v_result,'[]'::jsonb);
end;
$$;
revoke all on function public.crm_listar_paquetes_materiales(boolean) from public,anon;
grant execute on function public.crm_listar_paquetes_materiales(boolean) to authenticated;

create or replace function public.crm_guardar_paquete_materiales(
    p_paquete_id bigint,
    p_datos jsonb,
    p_items jsonb
) returns bigint
language plpgsql
security definer
set search_path=public
as $$
declare
    v_id bigint;
    v_nombre text:=btrim(coalesce(p_datos->>'nombre',''));
    v_descripcion text:=btrim(coalesce(p_datos->>'descripcion',''));
    v_categoria text:=coalesce(nullif(btrim(p_datos->>'categoria'),''),'General');
    v_activo boolean:=coalesce((p_datos->>'activo')::boolean,true);
    v_orden integer:=coalesce(nullif(p_datos->>'orden','')::integer,0);
    v_item jsonb;
    v_codigo text;
    v_cantidad numeric;
    v_total integer:=0;
begin
    if not public.crm_paquetes_es_administrador() then
        raise exception using errcode='42501',message='Solo Jefatura de Almacén puede administrar paquetes predeterminados.';
    end if;
    if v_nombre='' then raise exception 'Captura el nombre del paquete.'; end if;
    if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then raise exception 'La lista de materiales del paquete no es válida.'; end if;

    if coalesce(p_paquete_id,0)>0 then
        update public.crm_paquetes_materiales
        set nombre=v_nombre,descripcion=nullif(v_descripcion,''),categoria=v_categoria,activo=v_activo,orden=v_orden,updated_at=now()
        where id=p_paquete_id
        returning id into v_id;
        if v_id is null then raise exception 'El paquete seleccionado ya no existe.'; end if;
    else
        insert into public.crm_paquetes_materiales(nombre,descripcion,categoria,activo,orden,created_by)
        values(v_nombre,nullif(v_descripcion,''),v_categoria,v_activo,v_orden,auth.uid())
        returning id into v_id;
    end if;

    delete from public.crm_paquetes_materiales_items where paquete_id=v_id;
    for v_item in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
        v_codigo:=btrim(coalesce(v_item->>'codigo',v_item->>'materialCodigo',''));
        v_cantidad:=coalesce(nullif(coalesce(v_item->>'cantidad','0'),'')::numeric,0);
        if v_codigo='' or v_cantidad<=0 then raise exception 'Existe un material sin código o con cantidad inválida.'; end if;
        if not exists(select 1 from public.materiales m where m.codigo=v_codigo and coalesce(m.activo,true)=true) then
            raise exception 'El material % no existe o está inactivo en el catálogo.',v_codigo;
        end if;
        insert into public.crm_paquetes_materiales_items(paquete_id,material_codigo,cantidad,notas)
        values(v_id,v_codigo,v_cantidad,nullif(btrim(coalesce(v_item->>'notas','')),''))
        on conflict(paquete_id,material_codigo) do update set cantidad=excluded.cantidad,notas=excluded.notas,updated_at=now();
        v_total:=v_total+1;
    end loop;
    if v_activo and v_total=0 then
        raise exception 'Un paquete activo debe contener al menos un material.';
    end if;
    return v_id;
exception when unique_violation then
    raise exception 'Ya existe un paquete con ese nombre.';
end;
$$;
revoke all on function public.crm_guardar_paquete_materiales(bigint,jsonb,jsonb) from public,anon;
grant execute on function public.crm_guardar_paquete_materiales(bigint,jsonb,jsonb) to authenticated;

create or replace function public.crm_eliminar_paquete_materiales(p_paquete_id bigint)
returns boolean
language plpgsql
security definer
set search_path=public
as $$
begin
    if not public.crm_paquetes_es_administrador() then
        raise exception using errcode='42501',message='Solo Jefatura de Almacén puede eliminar paquetes predeterminados.';
    end if;
    if exists(select 1 from public.crm_solicitudes_paquetes s where s.paquete_id=p_paquete_id) then
        update public.crm_paquetes_materiales set activo=false,updated_at=now() where id=p_paquete_id;
        return true;
    end if;
    delete from public.crm_paquetes_materiales where id=p_paquete_id;
    return found;
end;
$$;
revoke all on function public.crm_eliminar_paquete_materiales(bigint) from public,anon;
grant execute on function public.crm_eliminar_paquete_materiales(bigint) to authenticated;

create or replace function public.crm_listar_proyectos_paquetes()
returns jsonb
language plpgsql
stable
security definer
set search_path=public
as $$
declare v_result jsonb;
begin
    if not public.crm_paquetes_usuario_activo() then
        raise exception using errcode='42501',message='Tu perfil no puede consultar proyectos para solicitudes internas.';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
        'proyecto',p.numero_proyecto,
        'numeroProyecto',p.numero_proyecto,
        'nombreProyecto',coalesce(p.nombre_proyecto,''),
        'cliente',coalesce(p.cliente,''),
        'responsableSkilled',coalesce(p.responsable_skilled,''),
        'estado',coalesce(p.estado,'')
    ) order by p.numero_proyecto),'[]'::jsonb)
    into v_result
    from public.proyectos p;
    return coalesce(v_result,'[]'::jsonb);
end;
$$;
revoke all on function public.crm_listar_proyectos_paquetes() from public,anon;
grant execute on function public.crm_listar_proyectos_paquetes() to authenticated;

create or replace function public.crm_solicitar_paquete_materiales(
    p_paquete_id bigint,
    p_cantidad integer default 1,
    p_proyecto text default null,
    p_destinatario text default null,
    p_prioridad text default 'normal',
    p_notas text default null
) returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_perfil record;
    v_paquete record;
    v_id bigint;
    v_folio text;
    v_cantidad integer:=greatest(1,least(coalesce(p_cantidad,1),100));
    v_proyecto text:=nullif(btrim(coalesce(p_proyecto,'')),'');
    v_destinatario text:=btrim(coalesce(p_destinatario,''));
    v_prioridad text:=lower(btrim(coalesce(p_prioridad,'normal')));
    v_count integer;
begin
    if not public.crm_paquetes_usuario_activo() then
        raise exception using errcode='42501',message='Tu perfil no puede solicitar paquetes de materiales.';
    end if;
    select p.id,coalesce(nullif(btrim(p.nombre),''),'Usuario') nombre,lower(coalesce(p.rol,'consulta')) rol
    into v_perfil from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true;
    select * into v_paquete from public.crm_paquetes_materiales where id=p_paquete_id and activo=true;
    if v_paquete.id is null then raise exception 'El paquete ya no está disponible.'; end if;
    select count(*) into v_count from public.crm_paquetes_materiales_items where paquete_id=v_paquete.id;
    if v_count=0 then raise exception 'Este paquete todavía no tiene materiales configurados.'; end if;
    if v_perfil.rol='tsi' and exists(
        select 1
        from public.crm_paquetes_materiales_items i
        left join public.materiales m on m.codigo=i.material_codigo
        where i.paquete_id=v_paquete.id and upper(btrim(coalesce(m.categoria,'')))<>'EPP'
    ) then
        raise exception using errcode='42501',message='TSI solo puede solicitar paquetes compuestos exclusivamente por EPP.';
    end if;
    if v_proyecto is not null and not exists(select 1 from public.proyectos where numero_proyecto=v_proyecto) then
        raise exception 'El proyecto seleccionado ya no existe.';
    end if;
    if v_destinatario='' then v_destinatario:=v_perfil.nombre; end if;
    if v_prioridad not in('normal','alta','urgente') then v_prioridad:='normal'; end if;

    insert into public.crm_solicitudes_paquetes(
        paquete_id,paquete_nombre,cantidad_paquetes,proyecto_numero,destinatario,solicitante_id,solicitante_nombre,solicitante_rol,prioridad,estado,notas
    ) values(
        v_paquete.id,v_paquete.nombre,v_cantidad,v_proyecto,v_destinatario,auth.uid(),v_perfil.nombre,v_perfil.rol,v_prioridad,'pendiente',nullif(btrim(coalesce(p_notas,'')),'')
    ) returning id into v_id;

    v_folio:='PAQ-'||to_char(now(),'YYMMDD')||'-'||lpad(v_id::text,6,'0');
    update public.crm_solicitudes_paquetes set folio=v_folio where id=v_id;

    insert into public.crm_solicitudes_paquetes_items(
        solicitud_id,material_codigo,descripcion,unidad,cantidad_por_paquete,cantidad_solicitada,cantidad_entregada
    )
    select v_id,i.material_codigo,coalesce(m.descripcion,i.material_codigo),coalesce(nullif(m.unidad,''),'pieza'),i.cantidad,i.cantidad*v_cantidad,0
    from public.crm_paquetes_materiales_items i
    left join public.materiales m on m.codigo=i.material_codigo
    where i.paquete_id=v_paquete.id;

    return jsonb_build_object('id',v_id,'folio',v_folio,'estado','pendiente');
end;
$$;
revoke all on function public.crm_solicitar_paquete_materiales(bigint,integer,text,text,text,text) from public,anon;
grant execute on function public.crm_solicitar_paquete_materiales(bigint,integer,text,text,text,text) to authenticated;

create or replace function public.crm_listar_solicitudes_paquetes(p_mias boolean default false)
returns jsonb
language plpgsql
stable
security definer
set search_path=public
as $$
declare
    v_operador boolean:=public.crm_paquetes_es_operador_almacen();
    v_result jsonb;
begin
    if not public.crm_paquetes_usuario_activo() then
        raise exception using errcode='42501',message='Tu perfil no puede consultar solicitudes de paquetes.';
    end if;
    select coalesce(jsonb_agg(obj order by obj->>'createdAt' desc),'[]'::jsonb)
    into v_result
    from (
        select jsonb_build_object(
            'id',s.id,
            'folio',coalesce(s.folio,''),
            'paqueteId',s.paquete_id,
            'paqueteNombre',s.paquete_nombre,
            'cantidadPaquetes',s.cantidad_paquetes,
            'proyecto',coalesce(s.proyecto_numero,''),
            'destinatario',coalesce(s.destinatario,''),
            'solicitanteId',s.solicitante_id,
            'solicitanteNombre',s.solicitante_nombre,
            'solicitanteRol',s.solicitante_rol,
            'prioridad',s.prioridad,
            'estado',s.estado,
            'notas',coalesce(s.notas,''),
            'notasAlmacen',coalesce(s.notas_almacen,''),
            'almacenId',s.almacen_id,
            'movimientoRequestId',coalesce(s.movimiento_request_id,''),
            'createdAt',s.created_at,
            'updatedAt',s.updated_at,
            'atendidaAt',s.atendida_at,
            'items',coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id',i.id,
                    'codigo',i.material_codigo,
                    'descripcion',i.descripcion,
                    'unidad',coalesce(i.unidad,''),
                    'cantidadPorPaquete',i.cantidad_por_paquete,
                    'cantidadSolicitada',i.cantidad_solicitada,
                    'cantidadEntregada',i.cantidad_entregada,
                    'almacenes',coalesce((
                        select jsonb_agg(jsonb_build_object('id',a.id,'nombre',a.nombre,'stock',coalesce(e.stock,0)) order by a.nombre)
                        from public.almacenes a
                        left join public.existencias_almacen e on e.almacen_id=a.id and e.material_codigo=i.material_codigo
                    ),'[]'::jsonb)
                ) order by i.descripcion,i.material_codigo)
                from public.crm_solicitudes_paquetes_items i where i.solicitud_id=s.id
            ),'[]'::jsonb)
        ) obj
        from public.crm_solicitudes_paquetes s
        where case
            when v_operador and not coalesce(p_mias,false) then true
            else s.solicitante_id=auth.uid()
        end
    ) q;
    return coalesce(v_result,'[]'::jsonb);
end;
$$;
revoke all on function public.crm_listar_solicitudes_paquetes(boolean) from public,anon;
grant execute on function public.crm_listar_solicitudes_paquetes(boolean) to authenticated;

create or replace function public.crm_actualizar_solicitud_paquete(
    p_solicitud_id bigint,
    p_estado text,
    p_notas text default null
) returns boolean
language plpgsql
security definer
set search_path=public
as $$
declare
    v_estado text:=lower(btrim(coalesce(p_estado,'')));
    v_operador boolean:=public.crm_paquetes_es_operador_almacen();
    v_owner boolean;
begin
    if not public.crm_paquetes_usuario_activo() then raise exception using errcode='42501',message='Tu perfil no puede actualizar solicitudes de paquetes.'; end if;
    select solicitante_id=auth.uid() into v_owner from public.crm_solicitudes_paquetes where id=p_solicitud_id;
    if coalesce(v_owner,false) and not v_operador then
        if v_estado<>'cancelada' then raise exception using errcode='42501',message='Solo puedes cancelar tu propia solicitud.'; end if;
        update public.crm_solicitudes_paquetes
        set estado='cancelada',notas_almacen=coalesce(nullif(btrim(coalesce(p_notas,'')),''),notas_almacen),updated_at=now()
        where id=p_solicitud_id and solicitante_id=auth.uid() and estado in('pendiente','preparacion');
        return found;
    end if;
    if not v_operador then raise exception using errcode='42501',message='Solo Almacén puede atender solicitudes de paquetes.'; end if;
    if v_estado not in('pendiente','preparacion','rechazada','cancelada') then raise exception 'Estado de solicitud no válido.'; end if;
    update public.crm_solicitudes_paquetes
    set estado=v_estado,notas_almacen=coalesce(nullif(btrim(coalesce(p_notas,'')),''),notas_almacen),
        atendida_por=case when v_estado in('rechazada','cancelada') then auth.uid() else atendida_por end,
        atendida_at=case when v_estado in('rechazada','cancelada') then now() else atendida_at end,updated_at=now()
    where id=p_solicitud_id and estado<>'entregada';
    return found;
end;
$$;
revoke all on function public.crm_actualizar_solicitud_paquete(bigint,text,text) from public,anon;
grant execute on function public.crm_actualizar_solicitud_paquete(bigint,text,text) to authenticated;

create or replace function public.crm_entregar_solicitud_paquete(
    p_solicitud_id bigint,
    p_almacen_id bigint,
    p_notas text default null
) returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_solicitud public.crm_solicitudes_paquetes%rowtype;
    v_item record;
    v_material record;
    v_almacen_nombre text;
    v_disponible numeric;
    v_restante numeric;
    v_request_id text;
    v_registros integer:=0;
begin
    if not public.crm_paquetes_es_operador_almacen() then
        raise exception using errcode='42501',message='Solo Almacén puede entregar paquetes de materiales.';
    end if;
    select * into v_solicitud from public.crm_solicitudes_paquetes where id=p_solicitud_id for update;
    if v_solicitud.id is null then raise exception 'La solicitud ya no existe.'; end if;
    if v_solicitud.estado in('entregada','rechazada','cancelada') then raise exception 'La solicitud ya está cerrada.'; end if;
    select nombre into v_almacen_nombre from public.almacenes where id=p_almacen_id;
    if coalesce(v_almacen_nombre,'')='' then raise exception 'Selecciona un almacén válido.'; end if;

    for v_item in
        select * from public.crm_solicitudes_paquetes_items where solicitud_id=v_solicitud.id order by id
    loop
        v_restante:=greatest(0,coalesce(v_item.cantidad_solicitada,0)-coalesce(v_item.cantidad_entregada,0));
        if v_restante<=0 then continue; end if;
        select coalesce(stock,0) into v_disponible
        from public.existencias_almacen
        where material_codigo=v_item.material_codigo and almacen_id=p_almacen_id
        for update;
        v_disponible:=coalesce(v_disponible,0);
        if v_disponible<v_restante then
            raise exception 'Stock insuficiente de % en %. Disponible: %, requerido: %.',v_item.descripcion,v_almacen_nombre,v_disponible,v_restante;
        end if;
    end loop;

    v_request_id:='PAQ-'||coalesce(nullif(v_solicitud.folio,''),v_solicitud.id::text);
    if exists(select 1 from public.movimientos where request_id=v_request_id) then
        v_request_id:=v_request_id||'-'||to_char(clock_timestamp(),'HH24MISSMS');
    end if;

    for v_item in
        select * from public.crm_solicitudes_paquetes_items where solicitud_id=v_solicitud.id order by id
    loop
        v_restante:=greatest(0,coalesce(v_item.cantidad_solicitada,0)-coalesce(v_item.cantidad_entregada,0));
        if v_restante<=0 then continue; end if;
        update public.existencias_almacen
        set stock=stock-v_restante,updated_at=now()
        where material_codigo=v_item.material_codigo and almacen_id=p_almacen_id;

        select codigo,descripcion,categoria,unidad,precio into v_material
        from public.materiales where codigo=v_item.material_codigo;
        if v_material.codigo is null then raise exception 'El material % ya no existe en catálogo.',v_item.material_codigo; end if;

        insert into public.movimientos(
            request_id,fecha,tipo,material_codigo,descripcion,cantidad,unidad,categoria_manual,proyecto,referencia,bodega_origen,motivo,precio_unitario,
            recibe_nombre,recibe_tipo,folio_entrega,alcance,stock_fuente,cantidad_stock_proyecto,cantidad_stock_general,cantidad_dentro_plan,cantidad_fuera_plan,
            tomar_del_almacen,es_no_listado
        ) values(
            v_request_id,now(),'salida',v_material.codigo,v_material.descripcion,v_restante,coalesce(nullif(v_material.unidad,''),v_item.unidad),v_material.categoria,
            nullif(btrim(coalesce(v_solicitud.proyecto_numero,'')),''),v_solicitud.folio,v_almacen_nombre,
            'Paquete predeterminado: '||v_solicitud.paquete_nombre||' · Solicitó: '||v_solicitud.solicitante_nombre||case when coalesce(v_solicitud.destinatario,'')<>'' then ' · Destino: '||v_solicitud.destinatario else '' end,
            coalesce(v_material.precio,0),nullif(v_solicitud.destinatario,''),'paquete_predeterminado',v_solicitud.folio,
            case when nullif(btrim(coalesce(v_solicitud.proyecto_numero,'')),'') is null then null else 'fuera_plan' end,
            'almacen_general',0,v_restante,0,case when nullif(btrim(coalesce(v_solicitud.proyecto_numero,'')),'') is null then 0 else v_restante end,false,false
        );

        update public.crm_solicitudes_paquetes_items
        set cantidad_entregada=cantidad_solicitada,updated_at=now()
        where id=v_item.id;
        v_registros:=v_registros+1;
    end loop;

    update public.crm_solicitudes_paquetes
    set estado='entregada',almacen_id=p_almacen_id,movimiento_request_id=v_request_id,notas_almacen=coalesce(nullif(btrim(coalesce(p_notas,'')),''),notas_almacen),
        atendida_por=auth.uid(),atendida_at=now(),updated_at=now()
    where id=v_solicitud.id;

    return jsonb_build_object('ok',true,'folio',v_solicitud.folio,'requestId',v_request_id,'registros',v_registros,'almacen',v_almacen_nombre);
end;
$$;
revoke all on function public.crm_entregar_solicitud_paquete(bigint,bigint,text) from public,anon;
grant execute on function public.crm_entregar_solicitud_paquete(bigint,bigint,text) to authenticated;

create or replace function public.crm_contar_solicitudes_paquetes()
returns integer
language plpgsql
stable
security definer
set search_path=public
as $$
declare v_count integer:=0;
begin
    if not public.crm_paquetes_usuario_activo() then return 0; end if;
    if public.crm_paquetes_es_operador_almacen() then
        select count(*) into v_count from public.crm_solicitudes_paquetes where estado in('pendiente','preparacion');
    else
        select count(*) into v_count from public.crm_solicitudes_paquetes where solicitante_id=auth.uid() and estado in('pendiente','preparacion');
    end if;
    return coalesce(v_count,0);
end;
$$;
revoke all on function public.crm_contar_solicitudes_paquetes() from public,anon;
grant execute on function public.crm_contar_solicitudes_paquetes() to authenticated;

