create or replace function public.crm_crear_material_incompleto_v76(
    p_codigo text,
    p_descripcion text,
    p_categoria text default null,
    p_unidad text default null,
    p_precio numeric default 0,
    p_codigo_marca text default null,
    p_moneda_costo text default 'MXN',
    p_origen text default 'alta_manual'
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_rol text;
    v_codigo text:=btrim(coalesce(p_codigo,''));
    v_descripcion text:=btrim(coalesce(p_descripcion,''));
    v_categoria text:=coalesce(nullif(btrim(coalesce(p_categoria,'')),''),'Sin clasificar');
    v_unidad text:=coalesce(nullif(btrim(coalesce(p_unidad,'')),''),'pieza');
    v_moneda text:=upper(btrim(coalesce(p_moneda_costo,'MXN')));
    v_codigo_marca text:=nullif(btrim(coalesce(p_codigo_marca,'')),'');
    v_origen text:=coalesce(nullif(btrim(coalesce(p_origen,'')),''),'alta_manual');
    v_row public.materiales%rowtype;
begin
    if auth.uid() is null then raise exception using errcode='42501',message='La sesión no está activa.'; end if;
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in ('administrador','jefe_almacen','almacen','proyectos','compras','tsi') then
        raise exception using errcode='42501',message='Tu perfil no puede crear materiales incompletos.';
    end if;
    if v_rol='tsi' and lower(v_categoria)<>'epp' then
        raise exception using errcode='42501',message='TSI solo puede registrar o solicitar materiales EPP.';
    end if;
    if v_codigo='' or v_descripcion='' then raise exception 'Código y descripción son obligatorios.'; end if;
    if v_moneda not in ('MXN','USD','EUR') then v_moneda:='MXN'; end if;
    select * into v_row from public.materiales where lower(btrim(codigo))=lower(v_codigo) limit 1;
    if found then
        update public.materiales set
            codigo_marca=coalesce(v_codigo_marca,codigo_marca),
            moneda_costo=coalesce(v_moneda,moneda_costo,'MXN'),
            updated_at=now()
        where codigo=v_row.codigo
        returning * into v_row;
        return jsonb_build_object('ok',true,'codigo',v_row.codigo,'existente',true);
    end if;
    if to_regclass('public.categorias_materiales') is not null then
        insert into public.categorias_materiales(nombre,activo,updated_at)
        values(v_categoria,true,now())
        on conflict(nombre) do update set activo=true,updated_at=now();
    end if;
    insert into public.materiales(codigo,descripcion,categoria,unidad,precio,codigo_marca,moneda_costo,imagen_url,es_incompleto,origen_alta,activo,updated_at)
    values(v_codigo,v_descripcion,v_categoria,v_unidad,greatest(coalesce(p_precio,0),0),v_codigo_marca,v_moneda,null,true,v_origen,true,now())
    returning * into v_row;
    return jsonb_build_object('ok',true,'codigo',v_row.codigo,'existente',false);
end;
$$;
revoke all on function public.crm_crear_material_incompleto_v76(text,text,text,text,numeric,text,text,text) from public,anon;
grant execute on function public.crm_crear_material_incompleto_v76(text,text,text,text,numeric,text,text,text) to authenticated,service_role;

create table if not exists public.tsi_solicitudes_epp(
    id bigint generated by default as identity primary key,
    folio text unique,
    solicitado_por uuid not null default auth.uid(),
    proyecto_numero text,
    destinatario text not null,
    observaciones text,
    estado text not null default 'pendiente',
    atendido_por uuid,
    notas_atencion text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint tsi_solicitudes_epp_estado_check check(estado in('pendiente','en_preparacion','entregada','rechazada','cancelada'))
);
create table if not exists public.tsi_solicitud_epp_items(
    id bigint generated by default as identity primary key,
    solicitud_id bigint not null references public.tsi_solicitudes_epp(id) on delete cascade,
    material_codigo text not null,
    descripcion text not null,
    marca text,
    codigo_marca text,
    unidad text,
    cantidad numeric not null,
    created_at timestamptz not null default now(),
    constraint tsi_solicitud_epp_items_cantidad_check check(cantidad>0)
);
create index if not exists tsi_solicitudes_epp_solicitado_idx on public.tsi_solicitudes_epp(solicitado_por,created_at desc);
create index if not exists tsi_solicitudes_epp_estado_idx on public.tsi_solicitudes_epp(estado,created_at desc);
create index if not exists tsi_solicitud_epp_items_solicitud_idx on public.tsi_solicitud_epp_items(solicitud_id);
alter table public.tsi_solicitudes_epp enable row level security;
alter table public.tsi_solicitud_epp_items enable row level security;
revoke all on public.tsi_solicitudes_epp from anon,authenticated;
revoke all on public.tsi_solicitud_epp_items from anon,authenticated;

create or replace function public.tsi_listar_epp_v76(p_filtro text default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_rol text; v_q text:=nullif(lower(btrim(coalesce(p_filtro,''))),''); v_result jsonb;
begin
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in('tsi','administrador','jefe_almacen','almacen') then raise exception using errcode='42501',message='Tu perfil no puede consultar el catálogo EPP de TSI.'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('codigo',m.codigo,'descripcion',m.descripcion,'categoria',m.categoria,'unidad',m.unidad,'marca',m.marca,'codigo_marca',m.codigo_marca,'stock',coalesce(x.stock,0)) order by m.descripcion),'[]'::jsonb)
    into v_result
    from public.materiales m
    left join lateral(select coalesce(sum(e.stock),0)::numeric stock from public.existencias_almacen e where e.material_codigo=m.codigo) x on true
    where coalesce(m.activo,true)=true and lower(btrim(coalesce(m.categoria,'')))='epp'
      and (v_q is null or lower(concat_ws(' ',m.codigo,m.descripcion,m.marca,m.codigo_marca,m.unidad)) like '%'||v_q||'%');
    return v_result;
end;$$;
revoke all on function public.tsi_listar_epp_v76(text) from public,anon;
grant execute on function public.tsi_listar_epp_v76(text) to authenticated;

create or replace function public.tsi_listar_proyectos_v76()
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_rol text; v_result jsonb;
begin
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in('tsi','administrador') then raise exception using errcode='42501',message='Tu perfil no puede consultar proyectos para solicitudes TSI.'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('proyecto',p.numero_proyecto,'nombre',p.nombre_proyecto,'responsable',p.responsable_skilled,'estado',p.estado) order by p.numero_proyecto),'[]'::jsonb)
    into v_result from public.proyectos p where lower(coalesce(p.estado,'activo')) not in('finalizado','cerrado','cancelado','inactivo');
    return v_result;
end;$$;
revoke all on function public.tsi_listar_proyectos_v76() from public,anon;
grant execute on function public.tsi_listar_proyectos_v76() to authenticated;

create or replace function public.tsi_crear_solicitud_epp_v76(p_proyecto text,p_destinatario text,p_observaciones text,p_items jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_rol text; v_id bigint; v_folio text; v_item jsonb; v_codigo text; v_cantidad numeric; v_material public.materiales%rowtype; v_count integer:=0;
begin
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in('tsi','administrador') then raise exception using errcode='42501',message='Solo TSI puede registrar estas solicitudes de EPP.'; end if;
    if nullif(btrim(coalesce(p_destinatario,'')),'') is null then raise exception 'El destinatario es obligatorio.'; end if;
    if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'Agrega al menos un material EPP.'; end if;
    if nullif(btrim(coalesce(p_proyecto,'')),'') is not null and not exists(select 1 from public.proyectos where numero_proyecto=btrim(p_proyecto)) then raise exception 'El proyecto indicado no existe.'; end if;
    insert into public.tsi_solicitudes_epp(folio,solicitado_por,proyecto_numero,destinatario,observaciones,estado)
    values('TEMP-'||replace(gen_random_uuid()::text,'-',''),auth.uid(),nullif(btrim(coalesce(p_proyecto,'')),''),btrim(p_destinatario),nullif(btrim(coalesce(p_observaciones,'')),''),'pendiente') returning id into v_id;
    v_folio:='TSI-EPP-'||to_char(current_date,'YYMMDD')||'-'||lpad(v_id::text,6,'0');
    update public.tsi_solicitudes_epp set folio=v_folio where id=v_id;
    for v_item in select value from jsonb_array_elements(p_items)
    loop
        v_codigo:=btrim(coalesce(v_item->>'codigo',''));
        v_cantidad:=coalesce(nullif(v_item->>'cantidad','')::numeric,0);
        if v_codigo='' or v_cantidad<=0 then raise exception 'Cada EPP debe tener código y cantidad mayor a cero.'; end if;
        select * into v_material from public.materiales where codigo=v_codigo and coalesce(activo,true)=true and lower(btrim(coalesce(categoria,'')))='epp';
        if not found then raise exception 'El material % no existe, está inactivo o no pertenece a EPP.',v_codigo; end if;
        insert into public.tsi_solicitud_epp_items(solicitud_id,material_codigo,descripcion,marca,codigo_marca,unidad,cantidad)
        values(v_id,v_material.codigo,v_material.descripcion,v_material.marca,v_material.codigo_marca,v_material.unidad,v_cantidad);
        v_count:=v_count+1;
    end loop;
    return jsonb_build_object('ok',true,'id',v_id,'folio',v_folio,'partidas',v_count);
exception when others then
    if v_id is not null then delete from public.tsi_solicitudes_epp where id=v_id; end if;
    raise;
end;$$;
revoke all on function public.tsi_crear_solicitud_epp_v76(text,text,text,jsonb) from public,anon;
grant execute on function public.tsi_crear_solicitud_epp_v76(text,text,text,jsonb) to authenticated;

create or replace function public.tsi_listar_solicitudes_epp_v76(p_solo_mias boolean default true)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_rol text; v_result jsonb;
begin
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in('tsi','administrador','jefe_almacen','almacen') then raise exception using errcode='42501',message='Tu perfil no puede consultar solicitudes EPP.'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'folio',s.folio,'proyecto_numero',s.proyecto_numero,'destinatario',s.destinatario,'observaciones',s.observaciones,'estado',s.estado,'notas_atencion',s.notas_atencion,'created_at',s.created_at,'updated_at',s.updated_at,'items',coalesce(i.items,'[]'::jsonb)) order by s.created_at desc),'[]'::jsonb)
    into v_result from public.tsi_solicitudes_epp s
    left join lateral(select coalesce(jsonb_agg(jsonb_build_object('material_codigo',x.material_codigo,'descripcion',x.descripcion,'marca',x.marca,'codigo_marca',x.codigo_marca,'unidad',x.unidad,'cantidad',x.cantidad) order by x.id),'[]'::jsonb) items from public.tsi_solicitud_epp_items x where x.solicitud_id=s.id) i on true
    where (v_rol='tsi' and s.solicitado_por=auth.uid()) or (v_rol<>'tsi' and (not coalesce(p_solo_mias,false) or s.solicitado_por=auth.uid()));
    return v_result;
end;$$;
revoke all on function public.tsi_listar_solicitudes_epp_v76(boolean) from public,anon;
grant execute on function public.tsi_listar_solicitudes_epp_v76(boolean) to authenticated;

create or replace function public.tsi_actualizar_solicitud_epp_v76(p_id bigint,p_estado text,p_notas text default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_rol text; v_estado text:=lower(btrim(coalesce(p_estado,''))); v_count integer;
begin
    select lower(btrim(rol)) into v_rol from public.perfiles_usuario where id=auth.uid() and activo=true;
    if v_rol not in('administrador','jefe_almacen','almacen') then raise exception using errcode='42501',message='Solo Almacén puede actualizar solicitudes EPP de TSI.'; end if;
    if v_estado not in('pendiente','en_preparacion','entregada','rechazada') then raise exception 'Estado no válido.'; end if;
    update public.tsi_solicitudes_epp set estado=v_estado,atendido_por=auth.uid(),notas_atencion=nullif(btrim(coalesce(p_notas,'')),''),updated_at=now() where id=p_id;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'La solicitud ya no existe.'; end if;
    return jsonb_build_object('ok',true,'id',p_id,'estado',v_estado);
end;$$;
revoke all on function public.tsi_actualizar_solicitud_epp_v76(bigint,text,text) from public,anon;
grant execute on function public.tsi_actualizar_solicitud_epp_v76(bigint,text,text) to authenticated;

create or replace function public.rh_resumen_carga_personal_v76(p_personal_ids bigint[])
returns table(personal_id bigint,proyectos_activos bigint,proyectos text[])
language plpgsql security definer set search_path=public as $$
begin
    if not public.crm_usuario_tiene_rol(array['administrador','rh']) then raise exception using errcode='42501',message='Tu perfil no puede consultar la carga de proyectos del personal.'; end if;
    return query
    select p.id,
           count(a.id) filter(where a.id is not null and lower(coalesce(pr.estado,'activo')) not in('finalizado','cerrado','cancelado','inactivo'))::bigint,
           coalesce(array_agg(a.proyecto_numero order by a.proyecto_numero) filter(where a.id is not null and lower(coalesce(pr.estado,'activo')) not in('finalizado','cerrado','cancelado','inactivo')),array[]::text[])
    from public.rh_personal p
    left join public.rh_proyecto_asignaciones a on a.personal_id=p.id and lower(coalesce(a.estado,''))='activo'
    left join public.proyectos pr on pr.numero_proyecto=a.proyecto_numero
    where p.id=any(coalesce(p_personal_ids,array[]::bigint[]))
    group by p.id;
end;$$;
revoke all on function public.rh_resumen_carga_personal_v76(bigint[]) from public,anon;
grant execute on function public.rh_resumen_carga_personal_v76(bigint[]) to authenticated;

