begin;

create table if not exists public.co_orden_firmas (
    id bigint generated by default as identity primary key,
    orden_compra text not null,
    tipo text not null check (tipo in ('solicito','elaboro','reviso','aprobo')),
    nombre text not null,
    firma_data_url text not null,
    user_id uuid not null default auth.uid(),
    firmado_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(orden_compra,tipo)
);
create index if not exists co_orden_firmas_orden_idx on public.co_orden_firmas(orden_compra);
alter table public.co_orden_firmas enable row level security;
drop policy if exists co_orden_firmas_select on public.co_orden_firmas;
create policy co_orden_firmas_select on public.co_orden_firmas for select to authenticated using (true);
drop policy if exists co_orden_firmas_insert on public.co_orden_firmas;
create policy co_orden_firmas_insert on public.co_orden_firmas for insert to authenticated with check (user_id=auth.uid());
drop policy if exists co_orden_firmas_update on public.co_orden_firmas;
create policy co_orden_firmas_update on public.co_orden_firmas for update to authenticated using (user_id=auth.uid() or public.crm_usuario_tiene_rol(array['administrador','compras'])) with check (user_id=auth.uid() or public.crm_usuario_tiene_rol(array['administrador','compras']));
drop policy if exists co_orden_firmas_delete on public.co_orden_firmas;
create policy co_orden_firmas_delete on public.co_orden_firmas for delete to authenticated using (user_id=auth.uid() or public.crm_usuario_tiene_rol(array['administrador','compras']));
grant select,insert,update,delete on public.co_orden_firmas to authenticated;
grant usage,select on sequence public.co_orden_firmas_id_seq to authenticated;

create or replace function public.co_crear_orden_directa_cotizacion_v96(
    p_cotizacion_id uuid,
    p_orden text,
    p_proveedor_id bigint,
    p_referencia text,
    p_solicitado_por text,
    p_notas text,
    p_items jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_cot public.co_cotizaciones%rowtype;
    v_order text:=upper(btrim(coalesce(p_orden,'')));
    v_provider_name text;
    v_provider_contact text;
    v_priority text;
    v_count integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','compras']) then
        raise exception using errcode='42501',message='Solo Compras o Administrador puede generar una orden directa desde cotización.';
    end if;
    select * into v_cot from public.co_cotizaciones where id=p_cotizacion_id for update;
    if not found then raise exception 'La solicitud de cotización ya no existe.'; end if;
    if exists(select 1 from public.solicitudes_compra where cotizacion_id=p_cotizacion_id and estado not in ('cancelada','recibida')) then
        raise exception 'Esta solicitud ya tiene una orden de compra activa vinculada.';
    end if;
    if coalesce(p_proveedor_id,0)<=0 then raise exception 'Selecciona el proveedor de la orden directa.'; end if;
    select coalesce(nullif(nombre_comercial,''),razon_social),contacto into v_provider_name,v_provider_contact
    from public.co_proveedores where id=p_proveedor_id and estado<>'inactivo';
    if v_provider_name is null then raise exception 'El proveedor seleccionado ya no está disponible.'; end if;
    if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'La orden no contiene partidas.'; end if;
    if v_order='' then v_order:='OC-DIR-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(md5(random()::text),1,3)); end if;
    v_priority:=case when lower(coalesce(v_cot.prioridad,'normal')) in('critica','urgente','alta') then 'urgente' else 'normal' end;

    insert into public.solicitudes_compra(
        folio,material_codigo,descripcion,categoria,unidad,almacen_id,almacen_nombre,
        existencia_actual,stock_minimo,stock_medio,stock_maximo,cantidad_solicitada,cantidad_recibida,
        prioridad,estado,proveedor,contacto_proveedor,orden_compra,grupo_orden,motivo,solicitado_por,
        fecha_requerida,fecha_orden_compra,referencia,estado_compras,cotizacion_id,cotizacion_item_id,
        proveedor_id,precio_cotizado,moneda,plazo_entrega_dias,origen_solicitud,justificacion_excepcion,created_at,updated_at
    )
    select
        'SC-DIR-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||lpad(row_number() over()::text,3,'0'),
        ci.material_codigo,ci.descripcion,m.categoria,coalesce(nullif(ci.unidad,''),m.unidad),ci.almacen_id,ci.almacen_nombre,
        ci.existencia_actual,ci.stock_minimo,ci.stock_medio,ci.stock_maximo,ci.cantidad,0,
        v_priority,'pendiente',v_provider_name,v_provider_contact,v_order,v_order,
        'Orden directa desde solicitud de cotización '||v_cot.folio||case when btrim(coalesce(p_notas,''))<>'' then ': '||btrim(p_notas) else '' end,
        coalesce(nullif(btrim(coalesce(p_solicitado_por,'')),''),v_cot.solicitado_por),
        v_cot.fecha_requerida,current_date,coalesce(nullif(btrim(coalesce(p_referencia,'')),''),v_cot.referencia),'en_revision',
        p_cotizacion_id,ci.id,p_proveedor_id,greatest(coalesce(x.precio_unitario,0),0),
        case upper(coalesce(x.moneda,'MXN')) when 'USD' then 'USD' when 'EUR' then 'EUR' else 'MXN' end,
        greatest(coalesce(x.plazo_entrega_dias,0),0),'cotizacion_directa','Orden directa sin comparación de propuestas',now(),now()
    from jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
    join public.co_cotizacion_items ci on ci.id=x.cotizacion_item_id and ci.cotizacion_id=p_cotizacion_id
    left join public.materiales m on lower(m.codigo)=lower(ci.material_codigo);
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se pudieron crear partidas para la orden directa.'; end if;

    update public.co_cotizaciones
       set estado='aprobada',aprobada_por=auth.uid(),aprobada_at=now(),revisada_por=coalesce(revisada_por,auth.uid()),revisada_at=coalesce(revisada_at,now()),oc_generada_at=now(),updated_at=now()
     where id=p_cotizacion_id;
    update public.co_cotizacion_items set estado='cerrado',proveedor_seleccionado_id=p_proveedor_id,updated_at=now() where cotizacion_id=p_cotizacion_id;
    return jsonb_build_object('ok',true,'orden',v_order,'materiales',v_count,'cotizacion_id',p_cotizacion_id,'origen','cotizacion_directa');
end;
$$;
revoke all on function public.co_crear_orden_directa_cotizacion_v96(uuid,text,bigint,text,text,text,jsonb) from public,anon;
grant execute on function public.co_crear_orden_directa_cotizacion_v96(uuid,text,bigint,text,text,text,jsonb) to authenticated;

