    ubicacion text,
    proveedor text,
    contacto_proveedor text,
    unidad text not null default 'PIEZA',
    stock numeric(16,4) not null default 0 check (stock >= 0),
    stock_minimo numeric(16,4) not null default 0 check (stock_minimo >= 0),
    stock_medio numeric(16,4) not null default 0 check (stock_medio >= 0),
    stock_maximo numeric(16,4) not null default 0 check (stock_maximo >= 0),
    precio numeric(16,4) not null default 0 check (precio >= 0),
    moneda_costo text not null default 'MXN' check (moneda_costo in ('MXN','USD','EUR')),
    imagen_url text,
