drop policy if exists "Recepción consulta co_tienda_solicitudes" on public.co_tienda_solicitudes;
create policy "Recepción consulta co_tienda_solicitudes" on public.co_tienda_solicitudes
for select to authenticated
using (public.crm_usuario_tiene_rol(array['administrador','recepcion']));
drop policy if exists "Recepción administra co_tienda_solicitudes" on public.co_tienda_solicitudes;
create policy "Recepción administra co_tienda_solicitudes" on public.co_tienda_solicitudes
