create or replace function public.co_crear_orden_directa_cotizacion_v103(
    p_cotizacion_id uuid,
    p_orden text,
    p_proveedor_id bigint,
    p_referencia text,
    p_solicitado_por text,
    p_notas text,
    p_items jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_cot public.co_cotizaciones%rowtype;
    v_order text:=upper(btrim(coalesce(p_orden,'')));
    v_provider_name text;
    v_provider_contact text;
    v_priority text;
    v_count integer:=0;
    v_remaining integer:=0;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','compras']) then
        raise exception using errcode='42501',message='Solo Compras o Administrador puede generar una orden directa desde cotización.';
    end if;
    if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then
        raise exception 'La orden no contiene partidas.';
    end if;
    if coalesce(p_proveedor_id,0)<=0 then
        raise exception 'Selecciona el proveedor de la orden directa.';
    end if;

    select * into v_cot from public.co_cotizaciones where id=p_cotizacion_id for update;
    if not found then raise exception 'La solicitud de cotización ya no existe.'; end if;

    select coalesce(nullif(nombre_comercial,''),razon_social),contacto
      into v_provider_name,v_provider_contact
      from public.co_proveedores
     where id=p_proveedor_id and estado<>'inactivo';
    if v_provider_name is null then raise exception 'El proveedor seleccionado ya no está disponible.'; end if;

    if exists(
        select 1
          from public.solicitudes_compra sc
          join jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
            on x.cotizacion_item_id=sc.cotizacion_item_id
         where sc.cotizacion_id=p_cotizacion_id
           and lower(coalesce(sc.estado,'')) not in ('cancelada','recibida')
    ) then
        raise exception 'Una o más partidas seleccionadas ya tienen una orden de compra activa.';
    end if;

    if exists(
        select 1
          from jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
          left join public.co_cotizacion_items ci on ci.id=x.cotizacion_item_id and ci.cotizacion_id=p_cotizacion_id
         where ci.id is null or ci.estado='cerrado'
    ) then
        raise exception 'Una o más partidas ya no están disponibles para generar orden.';
    end if;

    if v_order='' then
        v_order:='OC-DIR-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(md5(random()::text),1,3));
    end if;
    v_priority:=case when lower(coalesce(v_cot.prioridad,'normal')) in('critica','urgente','alta') then 'urgente' else 'normal' end;

    insert into public.solicitudes_compra(
        folio,material_codigo,descripcion,categoria,unidad,almacen_id,almacen_nombre,
        existencia_actual,stock_minimo,stock_medio,stock_maximo,cantidad_solicitada,cantidad_recibida,
        prioridad,estado,proveedor,contacto_proveedor,orden_compra,grupo_orden,motivo,solicitado_por,
        fecha_requerida,fecha_orden_compra,referencia,estado_compras,cotizacion_id,cotizacion_item_id,
        proveedor_id,precio_cotizado,moneda,plazo_entrega_dias,origen_solicitud,justificacion_excepcion,created_at,updated_at
    )
    select
        'SC-DIR-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||lpad(row_number() over()::text,3,'0'),
        ci.material_codigo,ci.descripcion,m.categoria,coalesce(nullif(ci.unidad,''),m.unidad),ci.almacen_id,ci.almacen_nombre,
        ci.existencia_actual,ci.stock_minimo,ci.stock_medio,ci.stock_maximo,ci.cantidad,0,
        v_priority,'pendiente',v_provider_name,v_provider_contact,v_order,v_order,
        'Orden directa desde solicitud de cotización '||v_cot.folio||case when btrim(coalesce(p_notas,''))<>'' then ': '||btrim(p_notas) else '' end,
        coalesce(nullif(btrim(coalesce(p_solicitado_por,'')),''),v_cot.solicitado_por),
        v_cot.fecha_requerida,current_date,coalesce(nullif(btrim(coalesce(p_referencia,'')),''),v_cot.referencia),'en_revision',
        p_cotizacion_id,ci.id,p_proveedor_id,greatest(coalesce(x.precio_unitario,0),0),
        case upper(coalesce(x.moneda,'MXN')) when 'USD' then 'USD' when 'EUR' then 'EUR' else 'MXN' end,
        greatest(coalesce(x.plazo_entrega_dias,0),0),'cotizacion_directa','Orden directa desde cotización',now(),now()
      from jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
      join public.co_cotizacion_items ci on ci.id=x.cotizacion_item_id and ci.cotizacion_id=p_cotizacion_id and ci.estado<>'cerrado'
      left join public.materiales m on lower(m.codigo)=lower(ci.material_codigo);
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No se pudieron crear partidas para la orden directa.'; end if;

    update public.co_cotizacion_ofertas o
       set estado=case when o.proveedor_id=p_proveedor_id then 'seleccionada' else 'descartada' end,
           updated_at=now()
     where o.cotizacion_item_id in (
        select x.cotizacion_item_id
          from jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
     );

    update public.co_cotizacion_items ci
       set estado='cerrado',
           proveedor_seleccionado_id=p_proveedor_id,
           oferta_seleccionada_id=(select o.id from public.co_cotizacion_ofertas o where o.cotizacion_item_id=ci.id and o.proveedor_id=p_proveedor_id order by o.id limit 1),
           updated_at=now()
     where ci.cotizacion_id=p_cotizacion_id
       and ci.id in (
          select x.cotizacion_item_id
            from jsonb_to_recordset(p_items) as x(cotizacion_item_id bigint,precio_unitario numeric,moneda text,plazo_entrega_dias integer)
       );

    select count(*) into v_remaining from public.co_cotizacion_items where cotizacion_id=p_cotizacion_id and estado<>'cerrado';

    if v_remaining=0 then
        update public.co_cotizaciones
           set estado='aprobada',
               aprobada_por=auth.uid(),
               aprobada_at=coalesce(aprobada_at,now()),
               revisada_por=coalesce(revisada_por,auth.uid()),
               revisada_at=coalesce(revisada_at,now()),
               oc_generada_at=coalesce(oc_generada_at,now()),
               updated_at=now()
         where id=p_cotizacion_id;
    else
        update public.co_cotizaciones
           set estado='comparada',
               revisada_por=coalesce(revisada_por,auth.uid()),
               revisada_at=coalesce(revisada_at,now()),
               oc_generada_at=coalesce(oc_generada_at,now()),
               updated_at=now()
         where id=p_cotizacion_id;
    end if;

    return jsonb_build_object('ok',true,'orden',v_order,'materiales',v_count,'pendientes',v_remaining,'cotizacion_id',p_cotizacion_id,'origen','cotizacion_directa_v103');
end;
$$;
revoke all on function public.co_crear_orden_directa_cotizacion_v103(uuid,text,bigint,text,text,text,jsonb) from public,anon;
grant execute on function public.co_crear_orden_directa_cotizacion_v103(uuid,text,bigint,text,text,text,jsonb) to authenticated;

create or replace function public.crm_sky_perfil_consultar_v103(p_fuente text,p_filtro text default null)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_role text;
      v_fuente text:=lower(btrim(coalesce(p_fuente,'')));
    v_filtro text:=nullif(btrim(coalesce(p_filtro,'')),'');
    v_result jsonb:='[]'::jsonb;
begin
    if auth.uid() is null then raise exception using errcode='42501',message='La sesión no está activa.'; end if;
    select lower(btrim(p.rol)) into v_role from public.perfiles_usuario p where p.id=auth.uid() and p.activo=true;
    if v_role is null then raise exception using errcode='42501',message='Tu perfil no está activo para Skill.'; end if;

    v_fuente:=case v_fuente
        when 'projectdetails' then 'proyectos'
        when 'purchases' then 'compras'
        when 'suppliers' then 'proveedores'
        when 'quotations' then 'cotizaciones'
        else v_fuente
    end;

    if v_role not in ('gerente_general','subgerente','sky_demo') then
        if v_role='administrador' then raise exception using errcode='42501',message='Skill Administración no tiene acceso transversal a datos operativos.'; end if;
        if v_role in ('jefe_almacen','almacen') and v_fuente not in ('materiales','categorias','almacenes','herramientas','vehiculos','proyectos','compras') then raise exception using errcode='42501',message='Skill Almacén no puede consultar esa fuente.'; end if;
        if v_role='compras' and v_fuente not in ('materiales','categorias','proyectos','proveedores','compras','cotizaciones') then raise exception using errcode='42501',message='Skill Compras no puede consultar esa fuente.'; end if;
        if v_role='proyectos' and v_fuente not in ('proyectos','materiales','categorias','compras') then raise exception using errcode='42501',message='Skill Proyectos no puede consultar esa fuente.'; end if;
        if v_role='planeacion' and v_fuente not in ('proyectos','materiales','categorias','compras') then raise exception using errcode='42501',message='Skill Planeación no puede consultar esa fuente.'; end if;
        if v_role='coordinacion' and v_fuente not in ('proyectos','vehiculos','compras') then raise exception using errcode='42501',message='Skill Coordinación no puede consultar esa fuente.'; end if;
        if v_role='logistica' and v_fuente not in ('proyectos','vehiculos','materiales','categorias') then raise exception using errcode='42501',message='Skill Logística no puede consultar esa fuente.'; end if;
        if v_role='recepcion' and v_fuente not in ('suministros','tienda') then raise exception using errcode='42501',message='Skill Recepción solo puede consultar Suministros, Tienda y la presencia limitada de Recepción.'; end if;
        if v_role='rh' and v_fuente not in ('personal','proyectos','vehiculos') then raise exception using errcode='42501',message='Skill RH no puede consultar esa fuente.'; end if;
        if v_role='finanzas' and v_fuente not in ('proyectos','compras','cotizaciones') then raise exception using errcode='42501',message='Skill Finanzas no puede consultar esa fuente.'; end if;
        if v_role='tsi' and v_fuente not in ('materiales','categorias','proyectos') then raise exception using errcode='42501',message='Skill TSI no puede consultar esa fuente.'; end if;
        if v_role='consulta' and v_fuente not in ('materiales','categorias') then raise exception using errcode='42501',message='Skill Consulta no puede consultar esa fuente.'; end if;
        if v_role not in ('administrador','jefe_almacen','almacen','compras','proyectos','planeacion','coordinacion','logistica','recepcion','rh','finanzas','tsi','consulta') then raise exception using errcode='42501',message='Skill no está habilitado para este perfil.'; end if;
    end if;

    if v_fuente='suministros' then
        select coalesce(jsonb_agg(jsonb_build_object(
            'id',s.id,'codigo',s.codigo,'descripcion',s.descripcion,'modismos',to_jsonb(s.modismos),'categoria',s.categoria,
            'marca',s.marca,'codigo_marca',s.codigo_marca,'ubicacion',s.ubicacion,
            'unidad',s.unidad,'stock',s.stock,'stock_minimo',s.stock_minimo,
            'precio',s.precio,'moneda_costo',s.moneda_costo,'imagen_url',s.imagen_url,'activo',s.activo
        ) order by s.descripcion),'[]'::jsonb)
          into v_result
          from public.re_suministros s
         where s.activo=true
           and (v_filtro is null or lower(concat_ws(' ',s.descripcion,s.categoria,s.marca,s.codigo_marca,s.ubicacion,s.unidad,array_to_string(s.modismos,' '))) like '%'||lower(v_filtro)||'%');
        return coalesce(v_result,'[]'::jsonb);
    end if;

    if v_fuente='tienda' then
        select coalesce(jsonb_agg(jsonb_build_object(
            'id',t.id,'folio',t.folio,'negocio',t.negocio,'producto',t.producto,'marcaEspecifica',t.marca_especifica,
            'presentacion',t.presentacion,'cantidad',t.cantidad,'unidad',t.unidad,'costoEstimado',t.costo_estimado,'moneda',t.moneda,
            'fechaRequerida',t.fecha_requerida,'prioridad',t.prioridad,'estado',t.estado,'solicitadoPor',t.solicitado_por,
            'responsableCompra',t.responsable_compra,'motivoNoViable',t.motivo_no_viable,'notas',t.notas,'createdAt',t.created_at
        ) order by t.created_at desc),'[]'::jsonb)
          into v_result
          from public.co_tienda_solicitudes t
         where v_filtro is null or lower(concat_ws(' ',t.folio,t.negocio,t.producto,t.marca_especifica,t.presentacion,t.estado,t.solicitado_por,t.responsable_compra,t.notas)) like '%'||lower(v_filtro)||'%';
        return coalesce(v_result,'[]'::jsonb);
    end if;

    return public.crm_sky_perfil_consultar(v_fuente,v_filtro);
end;
$$;
revoke all on function public.crm_sky_perfil_consultar_v103(text,text) from public,anon;
grant execute on function public.crm_sky_perfil_consultar_v103(text,text) to authenticated;

insert into public.crm_migraciones(version,aplicada_at)
values('CRM-V103-RECEPCION-SUMINISTROS-TIENDA-SKILL-OC-2026-08-19',now())
on conflict(version) do update set aplicada_at=excluded.aplicada_at;

notify pgrst,'reload schema';
commit;

select 'OK' as estado,
       'CRM-V103-RECEPCION-SUMINISTROS-TIENDA-SKILL-OC-2026-08-19' as revision,
       case when to_regclass('public.re_suministros') is not null then 'OK' else 'FALTA' end as suministros_recepcion,
       case when to_regprocedure('public.co_crear_orden_directa_cotizacion_v103(uuid,text,bigint,text,text,text,jsonb)') is not null then 'OK' else 'FALTA' end as orden_cotizacion_v103,
       case when to_regprocedure('public.crm_sky_perfil_consultar_v103(text,text)') is not null then 'OK' else 'FALTA' end as skill_perfiles_v103;


begin;

create table if not exists public.skill_reuniones(
    id uuid primary key default gen_random_uuid(),
    creador_id uuid not null references auth.users(id) on delete cascade,
    titulo text not null default 'Reunión',
    perfil text not null,
    participantes jsonb not null default '[]'::jsonb,
    inicio_at timestamptz,
    fin_at timestamptz,
    duracion_seg integer not null default 0,
    resumen text,
    acuerdos jsonb not null default '[]'::jsonb,
    estado text not null default 'finalizada',
    creado_at timestamptz not null default now(),
    actualizado_at timestamptz not null default now(),
    constraint skill_reuniones_estado_v105_check check(estado in ('borrador','en_curso','finalizada')),
    constraint skill_reuniones_duracion_v105_check check(duracion_seg between 0 and 86400)
);

create table if not exists public.skill_reunion_intervenciones(
    id bigint generated by default as identity primary key,
    reunion_id uuid not null references public.skill_reuniones(id) on delete cascade,
    turno integer not null default 0,
    hablante_clave text not null,
    hablante_nombre text not null,
    texto text not null,
    inicio_ms integer not null default 0,
    fin_ms integer not null default 0,
    confianza numeric(5,4),
    creado_at timestamptz not null default now(),
    constraint skill_reunion_intervenciones_turno_v105_check check(turno between 0 and 10000),
    constraint skill_reunion_intervenciones_tiempo_v105_check check(inicio_ms between 0 and 86400000 and fin_ms between 0 and 86400000),
    constraint skill_reunion_intervenciones_confianza_v105_check check(confianza is null or confianza between 0 and 1)
);

create index if not exists skill_reuniones_creador_v105_idx on public.skill_reuniones(creador_id,creado_at desc);
create index if not exists skill_reuniones_fecha_v105_idx on public.skill_reuniones(creado_at desc);
create index if not exists skill_reunion_intervenciones_reunion_v105_idx on public.skill_reunion_intervenciones(reunion_id,turno,id);

alter table public.skill_reuniones enable row level security;
alter table public.skill_reunion_intervenciones enable row level security;

drop policy if exists skill_reuniones_select_v105 on public.skill_reuniones;
create policy skill_reuniones_select_v105 on public.skill_reuniones
for select to authenticated
using (
    creador_id=auth.uid()
    or exists(
        select 1
        from public.perfiles_usuario p
        where p.id=auth.uid()
          and p.activo=true
          and lower(btrim(coalesce(p.rol,''))) in ('gerente_general','subgerente','sky_demo')
    )
);

drop policy if exists skill_reuniones_insert_v105 on public.skill_reuniones;
create policy skill_reuniones_insert_v105 on public.skill_reuniones
for insert to authenticated
with check (
    creador_id=auth.uid()
    and exists(
        select 1
        from public.perfiles_usuario p
        where p.id=auth.uid()
          and p.activo=true
          and lower(btrim(coalesce(p.rol,'')))=lower(btrim(coalesce(perfil,'')))
    )
);

drop policy if exists skill_reuniones_update_v105 on public.skill_reuniones;
create policy skill_reuniones_update_v105 on public.skill_reuniones
for update to authenticated
using (creador_id=auth.uid())
with check (creador_id=auth.uid());

drop policy if exists skill_reuniones_delete_v105 on public.skill_reuniones;
create policy skill_reuniones_delete_v105 on public.skill_reuniones
for delete to authenticated
using (creador_id=auth.uid());

drop policy if exists skill_reunion_intervenciones_select_v105 on public.skill_reunion_intervenciones;
create policy skill_reunion_intervenciones_select_v105 on public.skill_reunion_intervenciones
for select to authenticated
using (
    exists(
        select 1
        from public.skill_reuniones r
        where r.id=reunion_id
          and (
              r.creador_id=auth.uid()
              or exists(
                  select 1 from public.perfiles_usuario p
                  where p.id=auth.uid()
                    and p.activo=true
                    and lower(btrim(coalesce(p.rol,''))) in ('gerente_general','subgerente','sky_demo')
              )
          )
    )
);

drop policy if exists skill_reunion_intervenciones_insert_v105 on public.skill_reunion_intervenciones;
create policy skill_reunion_intervenciones_insert_v105 on public.skill_reunion_intervenciones
for insert to authenticated
with check (
    exists(select 1 from public.skill_reuniones r where r.id=reunion_id and r.creador_id=auth.uid())
);

drop policy if exists skill_reunion_intervenciones_update_v105 on public.skill_reunion_intervenciones;
create policy skill_reunion_intervenciones_update_v105 on public.skill_reunion_intervenciones
for update to authenticated
using (exists(select 1 from public.skill_reuniones r where r.id=reunion_id and r.creador_id=auth.uid()))
with check (exists(select 1 from public.skill_reuniones r where r.id=reunion_id and r.creador_id=auth.uid()));

drop policy if exists skill_reunion_intervenciones_delete_v105 on public.skill_reunion_intervenciones;
create policy skill_reunion_intervenciones_delete_v105 on public.skill_reunion_intervenciones
for delete to authenticated
using (exists(select 1 from public.skill_reuniones r where r.id=reunion_id and r.creador_id=auth.uid()));

grant select,insert,update,delete on public.skill_reuniones to authenticated;
grant select,insert,update,delete on public.skill_reunion_intervenciones to authenticated;
grant usage,select on sequence public.skill_reunion_intervenciones_id_seq to authenticated;

create or replace function public.crm_skill_reunion_guardar_v105(
    p_reunion jsonb,
    p_intervenciones jsonb default '[]'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_role text;
      v_id uuid;
    v_titulo text;
    v_participantes jsonb;
    v_acuerdos jsonb;
    v_inicio timestamptz;
    v_fin timestamptz;
    v_duracion integer;
    v_resumen text;
    v_estado text;
    v_item jsonb;
    v_count integer:=0;
begin
    if auth.uid() is null then
        raise exception using errcode='42501',message='La sesión no está activa.';
    end if;

    select lower(btrim(coalesce(p.rol,'')))
      into v_role
      from public.perfiles_usuario p
     where p.id=auth.uid() and p.activo=true;
    if v_role is null or v_role='' then
        raise exception using errcode='42501',message='Tu perfil no está activo para SKILL Reuniones.';
    end if;

    if p_reunion is null or jsonb_typeof(p_reunion)<>'object' then
        raise exception 'La información de la reunión no es válida.';
    end if;
    if p_intervenciones is null then p_intervenciones:='[]'::jsonb; end if;
    if jsonb_typeof(p_intervenciones)<>'array' then
        raise exception 'Las intervenciones de la reunión no son válidas.';
    end if;
    if jsonb_array_length(p_intervenciones)>1000 then
        raise exception 'La reunión supera el máximo de 1000 intervenciones por guardado.';
    end if;

    v_titulo:=left(coalesce(nullif(btrim(p_reunion->>'titulo'),''),'Reunión'),180);
    v_participantes:=case when jsonb_typeof(p_reunion->'participantes')='array' then p_reunion->'participantes' else '[]'::jsonb end;
    v_acuerdos:=case when jsonb_typeof(p_reunion->'acuerdos')='array' then p_reunion->'acuerdos' else '[]'::jsonb end;
    v_inicio:=case when coalesce(p_reunion->>'inicio_at','')~'^\\d{4}-\\d{2}-\\d{2}' then (p_reunion->>'inicio_at')::timestamptz else now() end;
    v_fin:=case when coalesce(p_reunion->>'fin_at','')~'^\\d{4}-\\d{2}-\\d{2}' then (p_reunion->>'fin_at')::timestamptz else now() end;
    v_duracion:=least(86400,greatest(0,coalesce(nullif(p_reunion->>'duracion_seg','')::integer,0)));
    v_resumen:=left(coalesce(p_reunion->>'resumen',''),12000);
    v_estado:=lower(coalesce(nullif(btrim(p_reunion->>'estado'),''),'finalizada'));
    if v_estado not in ('borrador','en_curso','finalizada') then v_estado:='finalizada'; end if;

    insert into public.skill_reuniones(
        creador_id,titulo,perfil,participantes,inicio_at,fin_at,duracion_seg,resumen,acuerdos,estado,creado_at,actualizado_at
    ) values(
        auth.uid(),v_titulo,v_role,v_participantes,v_inicio,v_fin,v_duracion,v_resumen,v_acuerdos,v_estado,now(),now()
    ) returning id into v_id;

    for v_item in select value from jsonb_array_elements(p_intervenciones)
    loop
        if jsonb_typeof(v_item)<>'object' then continue; end if;
        if btrim(coalesce(v_item->>'texto',''))='' then continue; end if;
        v_count:=v_count+1;
        insert into public.skill_reunion_intervenciones(
            reunion_id,turno,hablante_clave,hablante_nombre,texto,inicio_ms,fin_ms,confianza
        ) values(
            v_id,
            least(10000,greatest(0,coalesce(nullif(v_item->>'turno','')::integer,v_count))),
            left(coalesce(nullif(btrim(v_item->>'hablante_clave'),''),'voz-'||v_count::text),80),
            left(coalesce(nullif(btrim(v_item->>'hablante_nombre'),''),'Voz '||v_count::text),120),
            left(btrim(v_item->>'texto'),5000),
            least(86400000,greatest(0,coalesce(nullif(v_item->>'inicio_ms','')::integer,0))),
            least(86400000,greatest(0,coalesce(nullif(v_item->>'fin_ms','')::integer,0))),
            case
                when coalesce(v_item->>'confianza','')~'^([0-9]+([.][0-9]+)?)$'
                    then least(1::numeric,greatest(0::numeric,(v_item->>'confianza')::numeric))
                else null
            end
        );
    end loop;

    return jsonb_build_object(
        'ok',true,
        'id',v_id,
        'intervenciones',v_count,
        'audio_guardado',false,
        'huella_voz_guardada',false
    );
end;
$$;
revoke all on function public.crm_skill_reunion_guardar_v105(jsonb,jsonb) from public,anon;
grant execute on function public.crm_skill_reunion_guardar_v105(jsonb,jsonb) to authenticated;

create or replace function public.crm_skill_reuniones_listar_v105(p_limite integer default 20)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_role text;
      v_limit integer:=least(100,greatest(1,coalesce(p_limite,20)));
    v_result jsonb:='[]'::jsonb;
begin
    if auth.uid() is null then
        raise exception using errcode='42501',message='La sesión no está activa.';
    end if;
    select lower(btrim(coalesce(p.rol,''))) into v_role
      from public.perfiles_usuario p
     where p.id=auth.uid() and p.activo=true;
    if v_role is null or v_role='' then
        raise exception using errcode='42501',message='Tu perfil no está activo para SKILL Reuniones.';
    end if;

    select coalesce(jsonb_agg(x.item order by x.creado_at desc),'[]'::jsonb)
      into v_result
      from (
        select r.creado_at,
               jsonb_build_object(
                   'id',r.id,
                   'titulo',r.titulo,
                   'perfil',r.perfil,
                   'participantes',r.participantes,
                   'inicio_at',r.inicio_at,
                   'fin_at',r.fin_at,
                   'duracion_seg',r.duracion_seg,
                   'resumen',r.resumen,
                   'acuerdos',r.acuerdos,
                   'estado',r.estado,
                   'creado_at',r.creado_at,
                   'creador_id',r.creador_id,
                   'intervenciones',(select count(*) from public.skill_reunion_intervenciones i where i.reunion_id=r.id)
               ) item
          from public.skill_reuniones r
         where r.creador_id=auth.uid()
            or v_role in ('gerente_general','subgerente','sky_demo')
         order by r.creado_at desc
         limit v_limit
      ) x;
    return coalesce(v_result,'[]'::jsonb);
end;
$$;
revoke all on function public.crm_skill_reuniones_listar_v105(integer) from public,anon;
grant execute on function public.crm_skill_reuniones_listar_v105(integer) to authenticated;

