commit;


-- Automatización de nómina integrada al SQL maestro.
-- No sustituye secretos existentes: si ya configuraste rh_nomina_cron_secret, lo conserva.
do $crm_v105_ext$
begin
    begin
        execute 'create extension if not exists pg_cron';
    exception when insufficient_privilege or feature_not_supported then
        raise notice 'pg_cron no pudo instalarse automáticamente; actívalo desde Supabase si usarás la automatización de nómina.';
    end;
    begin
        execute 'create extension if not exists pg_net';
    exception when insufficient_privilege or feature_not_supported then
        raise notice 'pg_net no pudo instalarse automáticamente; actívalo desde Supabase si usarás la automatización de nómina.';
    end;
end
$crm_v105_ext$;

do $crm_v105_vault$
declare
    v_id uuid;
begin
    if to_regclass('vault.secrets') is null then
        raise notice 'Vault no está disponible; se omite la configuración automática de secretos de nómina.';
        return;
    end if;

    execute 'select id from vault.secrets where name=$1 limit 1' into v_id using 'rh_nomina_function_url';
    if v_id is null then
        perform vault.create_secret(
            'https://cuxnzqbszzrfnrinxbdp.supabase.co/functions/v1/rh-enviar-nomina-whatsapp',
            'rh_nomina_function_url',
            'URL Edge Function nómina RH'
        );
    end if;

    v_id:=null;
    execute 'select id from vault.secrets where name=$1 limit 1' into v_id using 'rh_nomina_cron_secret';
    if v_id is null then
        perform vault.create_secret(
            'REEMPLAZAR_POR_EL_MISMO_CRON_SHARED_SECRET_DE_EDGE_FUNCTIONS',
            'rh_nomina_cron_secret',
            'Secreto compartido para nómina automática'
        );
        raise notice 'Se creó el secreto rh_nomina_cron_secret con valor de reemplazo. Configúralo antes de habilitar envíos automáticos reales.';
    end if;
exception when undefined_function or invalid_schema_name then
    raise notice 'Vault no pudo configurarse automáticamente; conserva/configura los secretos manualmente desde Supabase.';
end
$crm_v105_vault$;

do $crm_v105_cron$
declare
    v_job_sql text;
begin
    if to_regclass('cron.job') is null or to_regclass('net._http_response') is null then
        raise notice 'pg_cron/pg_net no están listos; se omite el job de nómina.';
        return;
    end if;

    execute 'select cron.unschedule(jobid) from cron.job where jobname=$1' using 'rh-nomina-informativas-v75';

    v_job_sql := $job$
        select net.http_post(
            url := (select decrypted_secret from vault.decrypted_secrets where name='rh_nomina_function_url' limit 1),
            headers := jsonb_build_object(
                'Content-Type','application/json',
                'x-cron-secret',(select decrypted_secret from vault.decrypted_secrets where name='rh_nomina_cron_secret' limit 1)
            ),
            body := '{"mode":"auto"}'::jsonb,
            timeout_milliseconds := 30000
        );
    $job$;

    perform cron.schedule('rh-nomina-informativas-v75','*/15 * * * *',v_job_sql);
exception when undefined_function or invalid_schema_name or insufficient_privilege then
    raise notice 'No fue posible programar rh-nomina-informativas-v75 automáticamente.';
end
$crm_v105_cron$;

select 'OK' as estado,
       'CRM-V105-RECEPCION-SKILL-REUNIONES-SQL-MAESTRO-2026-08-19' as revision,
       case when to_regclass('public.skill_reuniones') is not null then 'OK' else 'FALTA' end as skill_reuniones,
       case when to_regclass('public.skill_reunion_intervenciones') is not null then 'OK' else 'FALTA' end as skill_intervenciones,
       case when to_regprocedure('public.crm_skill_reunion_guardar_v105(jsonb,jsonb)') is not null then 'OK' else 'FALTA' end as guardar_reunion,
       case when to_regprocedure('public.crm_skill_reuniones_listar_v105(integer)') is not null then 'OK' else 'FALTA' end as listar_reuniones;


begin;

create table if not exists public.re_bodeguita_racks (
    id bigint generated by default as identity primary key,
    nombre text not null,
    orden integer not null default 1 check (orden >= 1),
    notas text,
    activo boolean not null default true,
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create table if not exists public.re_bodeguita_niveles (
    id bigint generated by default as identity primary key,
    rack_id bigint not null references public.re_bodeguita_racks(id) on update cascade on delete cascade,
    nombre text not null,
    orden integer not null default 1 check (orden >= 1),
    cajones integer not null default 1 check (cajones between 1 and 200),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(rack_id,orden)
);

create table if not exists public.re_bodeguita_asignaciones (
    id bigint generated by default as identity primary key,
    suministro_id bigint not null references public.re_suministros(id) on update cascade on delete cascade,
    nivel_id bigint not null references public.re_bodeguita_niveles(id) on update cascade on delete cascade,
    cajon integer not null check (cajon >= 1),
    creado_por uuid references auth.users(id) on delete set null default auth.uid(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    unique(suministro_id)
);

create index if not exists re_bodeguita_niveles_rack_idx on public.re_bodeguita_niveles(rack_id,orden);
create index if not exists re_bodeguita_asignaciones_pos_idx on public.re_bodeguita_asignaciones(nivel_id,cajon);

drop trigger if exists trg_re_bodeguita_racks_fecha on public.re_bodeguita_racks;
create trigger trg_re_bodeguita_racks_fecha before update on public.re_bodeguita_racks for each row execute function public.co_actualizar_fecha();
drop trigger if exists trg_re_bodeguita_niveles_fecha on public.re_bodeguita_niveles;
create trigger trg_re_bodeguita_niveles_fecha before update on public.re_bodeguita_niveles for each row execute function public.co_actualizar_fecha();
drop trigger if exists trg_re_bodeguita_asignaciones_fecha on public.re_bodeguita_asignaciones;
create trigger trg_re_bodeguita_asignaciones_fecha before update on public.re_bodeguita_asignaciones for each row execute function public.co_actualizar_fecha();

create or replace function public.re_bodeguita_validar_nivel_v107()
returns trigger
language plpgsql
set search_path=public
as $$
begin
    if exists(
        select 1 from public.re_bodeguita_asignaciones a
        where a.nivel_id=new.id and a.cajon>new.cajones
    ) then
        raise exception 'No puedes reducir el nivel a % cajones porque todavía hay suministros acomodados en cajones superiores.',new.cajones;
    end if;
    return new;
end;
$$;
drop trigger if exists trg_re_bodeguita_validar_nivel_v107 on public.re_bodeguita_niveles;
create trigger trg_re_bodeguita_validar_nivel_v107 before update of cajones on public.re_bodeguita_niveles for each row execute function public.re_bodeguita_validar_nivel_v107();

alter table public.re_bodeguita_racks enable row level security;
alter table public.re_bodeguita_niveles enable row level security;
alter table public.re_bodeguita_asignaciones enable row level security;

drop policy if exists "Recepción administra re_bodeguita_racks" on public.re_bodeguita_racks;
create policy "Recepción administra re_bodeguita_racks" on public.re_bodeguita_racks for all to authenticated
using (public.crm_usuario_tiene_rol(array['administrador','recepcion']))
with check (public.crm_usuario_tiene_rol(array['administrador','recepcion']));
drop policy if exists "Recepción administra re_bodeguita_niveles" on public.re_bodeguita_niveles;
create policy "Recepción administra re_bodeguita_niveles" on public.re_bodeguita_niveles for all to authenticated
using (public.crm_usuario_tiene_rol(array['administrador','recepcion']))
with check (public.crm_usuario_tiene_rol(array['administrador','recepcion']));
drop policy if exists "Recepción administra re_bodeguita_asignaciones" on public.re_bodeguita_asignaciones;
create policy "Recepción administra re_bodeguita_asignaciones" on public.re_bodeguita_asignaciones for all to authenticated
using (public.crm_usuario_tiene_rol(array['administrador','recepcion']))
with check (public.crm_usuario_tiene_rol(array['administrador','recepcion']));

grant select,insert,update,delete on public.re_bodeguita_racks,public.re_bodeguita_niveles,public.re_bodeguita_asignaciones to authenticated;
grant usage,select on sequence public.re_bodeguita_racks_id_seq,public.re_bodeguita_niveles_id_seq,public.re_bodeguita_asignaciones_id_seq to authenticated;

create or replace function public.re_bodeguita_asignar_suministro_v107(
    p_suministro_id bigint,
    p_nivel_id bigint default null,
    p_cajon integer default null
)
returns jsonb
language plpgsql
security definer
set search_path=public,auth
as $$
declare
    v_nivel public.re_bodeguita_niveles%rowtype;
    v_rack public.re_bodeguita_racks%rowtype;
    v_ubicacion text;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','recepcion']) then
        raise exception using errcode='42501',message='Solo Recepción puede organizar la Bodeguita.';
    end if;
    if not exists(select 1 from public.re_suministros where id=p_suministro_id and activo=true) then
        raise exception 'El suministro ya no está disponible.';
    end if;
    if p_nivel_id is null or p_cajon is null then
        delete from public.re_bodeguita_asignaciones where suministro_id=p_suministro_id;
        update public.re_suministros set ubicacion=null,updated_at=now() where id=p_suministro_id;
        return jsonb_build_object('ok',true,'suministro_id',p_suministro_id,'ubicacion',null);
    end if;
    select * into v_nivel from public.re_bodeguita_niveles where id=p_nivel_id;
    if not found then raise exception 'El nivel seleccionado ya no existe.'; end if;
    if p_cajon<1 or p_cajon>v_nivel.cajones then raise exception 'El cajón seleccionado no existe en este nivel.'; end if;
    select * into v_rack from public.re_bodeguita_racks where id=v_nivel.rack_id and activo=true;
    if not found then raise exception 'El rack seleccionado ya no está activo.'; end if;
    insert into public.re_bodeguita_asignaciones(suministro_id,nivel_id,cajon,creado_por,created_at,updated_at)
    values(p_suministro_id,p_nivel_id,p_cajon,auth.uid(),now(),now())
    on conflict(suministro_id) do update set nivel_id=excluded.nivel_id,cajon=excluded.cajon,updated_at=now();
    v_ubicacion:='Bodeguita · '||v_rack.nombre||' · '||v_nivel.nombre||' · Cajón '||p_cajon;
    update public.re_suministros set ubicacion=v_ubicacion,updated_at=now() where id=p_suministro_id;
    return jsonb_build_object('ok',true,'suministro_id',p_suministro_id,'nivel_id',p_nivel_id,'cajon',p_cajon,'ubicacion',v_ubicacion);
end;
$$;
revoke all on function public.re_bodeguita_asignar_suministro_v107(bigint,bigint,integer) from public,anon;
grant execute on function public.re_bodeguita_asignar_suministro_v107(bigint,bigint,integer) to authenticated;

alter table if exists public.solicitudes_compra alter column material_codigo drop not null;
alter table if exists public.solicitudes_compra alter column almacen_id drop not null;

create or replace function public.co_crear_orden_libre_v107(
    p_orden text,
    p_proveedor_id bigint,
    p_almacen_id bigint,
    p_proyecto text,
    p_prioridad text,
    p_fecha_requerida date,
    p_referencia text,
    p_solicitado_por text,
    p_justificacion text,
    p_items jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
    v_order text:=upper(btrim(coalesce(p_orden,'')));
    v_provider_name text;
    v_provider_contact text;
    v_warehouse_name text:='Por definir';
    v_project text:=nullif(btrim(coalesce(p_proyecto,'')),'');
    v_priority text;
    v_count integer:=0;
    v_group text;
begin
    if not public.crm_usuario_tiene_rol(array['administrador','compras']) then
        raise exception using errcode='42501',message='Solo Compras o Administrador puede crear una orden libre.';
    end if;
    if p_almacen_id is not null then
        select nombre into v_warehouse_name from public.almacenes where id=p_almacen_id;
        if v_warehouse_name is null then raise exception 'El almacén destino seleccionado ya no existe.'; end if;
    end if;
    if v_project is not null and not exists(select 1 from public.proyectos where numero_proyecto=v_project) then
        raise exception 'El proyecto seleccionado ya no existe.';
    end if;
    if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then
        raise exception 'Agrega al menos una partida a la orden.';
    end if;
    if p_proveedor_id is not null then
        select coalesce(nullif(nombre_comercial,''),razon_social),contacto into v_provider_name,v_provider_contact
        from public.co_proveedores where id=p_proveedor_id and estado<>'inactivo';
        if v_provider_name is null then raise exception 'El proveedor seleccionado ya no está disponible.'; end if;
    end if;
    if v_order='' then v_order:='OC-LIB-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(md5(random()::text),1,3)); end if;
    v_group:=v_order;
    v_priority:=case when lower(coalesce(p_prioridad,'normal')) in('critica','urgente','alta') then 'urgente' else 'normal' end;

    insert into public.solicitudes_compra(
        folio,material_codigo,descripcion,categoria,unidad,almacen_id,almacen_nombre,
        existencia_actual,stock_minimo,stock_medio,stock_maximo,cantidad_solicitada,cantidad_recibida,
        prioridad,estado,proveedor,contacto_proveedor,orden_compra,grupo_orden,motivo,solicitado_por,
        fecha_requerida,fecha_orden_compra,referencia,estado_compras,proveedor_id,precio_cotizado,moneda,
        origen_solicitud,justificacion_excepcion,proyecto_numero,created_at,updated_at
    )
    select
        'SC-LIB-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||lpad(row_number() over()::text,3,'0'),
        nullif(btrim(x.material_codigo),''),
        coalesce(nullif(btrim(x.descripcion),''),m.descripcion),
        coalesce(nullif(btrim(x.categoria),''),m.categoria,'Compra libre'),
        coalesce(nullif(btrim(x.unidad),''),m.unidad,'PIEZA'),
        p_almacen_id,v_warehouse_name,
        coalesce(e.stock,0),coalesce(e.stock_minimo,0),coalesce(e.stock_medio,0),coalesce(e.stock_maximo,0),
        greatest(coalesce(x.cantidad,0),0),0,
        v_priority,'pendiente',v_provider_name,v_provider_contact,v_order,v_group,
        'Orden libre temporal'||case when btrim(coalesce(p_justificacion,''))<>'' then ': '||btrim(p_justificacion) else '' end,
        nullif(btrim(coalesce(p_solicitado_por,'')),''),p_fecha_requerida,current_date,
        nullif(btrim(coalesce(p_referencia,'')),''),'en_revision',p_proveedor_id,
        greatest(coalesce(x.precio_unitario,0),0),case upper(coalesce(x.moneda,'MXN')) when 'USD' then 'USD' when 'EUR' then 'EUR' else 'MXN' end,
        'manual_libre_temporal',nullif(btrim(coalesce(p_justificacion,'')),''),v_project,now(),now()
    from jsonb_to_recordset(p_items) as x(material_codigo text,descripcion text,categoria text,unidad text,cantidad numeric,precio_unitario numeric,moneda text)
    left join public.materiales m on lower(m.codigo)=lower(nullif(btrim(x.material_codigo),''))
    left join public.existencias_almacen e on e.material_codigo=m.codigo and e.almacen_id=p_almacen_id
    where nullif(btrim(coalesce(x.descripcion,m.descripcion,'')),'') is not null and coalesce(x.cantidad,0)>0;
    get diagnostics v_count=row_count;
    if v_count=0 then raise exception 'No hay partidas válidas para crear la orden.'; end if;
    return jsonb_build_object('ok',true,'orden',v_order,'materiales',v_count,'origen','manual_libre_temporal');
end;
$$;
revoke all on function public.co_crear_orden_libre_v107(text,bigint,bigint,text,text,date,text,text,text,jsonb) from public,anon;
grant execute on function public.co_crear_orden_libre_v107(text,bigint,bigint,text,text,date,text,text,text,jsonb) to authenticated;

