       case when to_regprocedure('public.re_bodeguita_asignar_suministro_v107(bigint,bigint,integer)') is not null then 'OK' else 'FALTA' end as acomodar_suministro,
       case when to_regprocedure('public.co_crear_orden_libre_v107(text,bigint,bigint,text,text,date,text,text,text,jsonb)') is not null then 'OK' else 'FALTA' end as orden_libre;

