begin;

alter table public.co_tienda_solicitudes add column if not exists suministro_id bigint;
alter table public.co_tienda_solicitudes add column if not exists cantidad_recibida numeric(16,4) not null default 0;
alter table public.co_tienda_solicitudes add column if not exists precio_ultimo numeric(16,2) not null default 0;
alter table public.co_tienda_solicitudes add column if not exists fecha_ultima_recepcion timestamptz;
alter table public.co_tienda_solicitudes add column if not exists recibido_por text;

do $crm_v108_fk$
begin
  if not exists(select 1 from pg_constraint where conname='co_tienda_suministro_id_fkey') then
    alter table public.co_tienda_solicitudes
      add constraint co_tienda_suministro_id_fkey foreign key(suministro_id)
      references public.re_suministros(id) on update cascade on delete set null;
  end if;
end
$crm_v108_fk$;

create table if not exists public.re_tienda_recepciones (
  id bigint generated by default as identity primary key,
  folio text not null,
  tienda_item_id bigint not null references public.co_tienda_solicitudes(id) on update cascade on delete cascade,
  suministro_id bigint references public.re_suministros(id) on update cascade on delete set null,
  cantidad numeric(16,4) not null check(cantidad>0),
  precio_unitario numeric(16,2) not null default 0 check(precio_unitario>=0),
  recibido_por text,
  creado_por uuid references auth.users(id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);
create index if not exists re_tienda_recepciones_folio_idx on public.re_tienda_recepciones(folio,created_at desc);
create index if not exists re_tienda_recepciones_item_idx on public.re_tienda_recepciones(tienda_item_id);

create or replace function public.re_tienda_proteger_partida_recibida_v108()
returns trigger language plpgsql as $$
begin
  if coalesce(old.cantidad_recibida,0)>0 then
    raise exception 'No se puede eliminar una partida que ya tiene recepción física registrada.';
  end if;
  return old;
end;
$$;
drop trigger if exists trg_re_tienda_proteger_partida_recibida_v108 on public.co_tienda_solicitudes;
create trigger trg_re_tienda_proteger_partida_recibida_v108 before delete on public.co_tienda_solicitudes for each row execute function public.re_tienda_proteger_partida_recibida_v108();

alter table public.re_tienda_recepciones enable row level security;
drop policy if exists "Recepción administra re_tienda_recepciones" on public.re_tienda_recepciones;
create policy "Recepción administra re_tienda_recepciones" on public.re_tienda_recepciones for all to authenticated
using (public.crm_usuario_tiene_rol(array['recepcion','administrador']))
with check (public.crm_usuario_tiene_rol(array['recepcion','administrador']));
grant select,insert,update,delete on public.re_tienda_recepciones to authenticated;
grant usage,select on sequence public.re_tienda_recepciones_id_seq to authenticated;

create or replace function public.re_recibir_lista_compra_v108(p_folio text,p_items jsonb,p_recibido_por text default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_entry jsonb;
  v_item public.co_tienda_solicitudes%rowtype;
  v_supply_id bigint;
  v_qty numeric;
  v_price numeric;
  v_remaining numeric;
  v_count integer:=0;
  v_complete boolean;
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then raise exception using errcode='42501',message='Solo Recepción puede registrar compras recibidas.'; end if;
  if nullif(btrim(coalesce(p_folio,'')),'') is null then raise exception 'Falta el folio de la lista.'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' then raise exception 'No hay partidas para recibir.'; end if;

  for v_entry in select value from jsonb_array_elements(p_items)
  loop
    select * into v_item from public.co_tienda_solicitudes
    where id=(v_entry->>'item_id')::bigint and folio=p_folio for update;
    if not found then raise exception 'Una partida ya no pertenece a la lista %.',p_folio; end if;
    v_qty:=greatest(coalesce((v_entry->>'cantidad')::numeric,0),0);
    if v_qty<=0 then continue; end if;
    v_remaining:=greatest(v_item.cantidad-coalesce(v_item.cantidad_recibida,0),0);
    if v_qty>v_remaining then raise exception 'La cantidad recibida de % supera lo pendiente (%).',v_item.producto,v_remaining; end if;
    v_price:=greatest(coalesce((v_entry->>'precio_unitario')::numeric,v_item.costo_estimado,0),0);
    v_supply_id:=v_item.suministro_id;
    if v_supply_id is null then
      select id into v_supply_id from public.re_suministros
      where activo=true and lower(btrim(descripcion))=lower(btrim(v_item.producto))
      order by id limit 1;
    end if;
    if v_supply_id is not null then
      update public.re_suministros
      set stock=coalesce(stock,0)+v_qty,
          precio=case when v_price>0 then v_price else precio end,
          updated_at=now()
      where id=v_supply_id and activo=true;
    end if;
    update public.co_tienda_solicitudes
    set suministro_id=coalesce(suministro_id,v_supply_id),
        cantidad_recibida=coalesce(cantidad_recibida,0)+v_qty,
        costo_estimado=case when v_price>0 then v_price else costo_estimado end,
        precio_ultimo=v_price,
        fecha_ultima_recepcion=now(),
        recibido_por=nullif(btrim(coalesce(p_recibido_por,'')),''),
        updated_at=now()
    where id=v_item.id;
    insert into public.re_tienda_recepciones(folio,tienda_item_id,suministro_id,cantidad,precio_unitario,recibido_por)
    values(p_folio,v_item.id,v_supply_id,v_qty,v_price,nullif(btrim(coalesce(p_recibido_por,'')),''));
    v_count:=v_count+1;
  end loop;

  select bool_and(coalesce(cantidad_recibida,0)>=cantidad) into v_complete
  from public.co_tienda_solicitudes where folio=p_folio;
  update public.co_tienda_solicitudes
  set estado=case when coalesce(v_complete,false) then 'comprado' else 'en_compra' end,updated_at=now()
  where folio=p_folio and estado not in ('cancelado','no_viable');
  return jsonb_build_object('ok',true,'folio',p_folio,'partidas_recibidas',v_count,'completa',coalesce(v_complete,false));
end;
$$;
revoke all on function public.re_recibir_lista_compra_v108(text,jsonb,text) from public,anon;
grant execute on function public.re_recibir_lista_compra_v108(text,jsonb,text) to authenticated;

