create policy "Recepción administra re_entrega_suministro_items" on public.re_entrega_suministro_items for all to authenticated
using (public.crm_usuario_tiene_rol(array['recepcion','administrador']))
with check (public.crm_usuario_tiene_rol(array['recepcion','administrador']));
