create or replace function public.re_registrar_entrega_suministros_v108(p_entregado_a text,p_area text,p_notas text,p_firma_data text,p_items jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_folio text;
  v_entrega_id bigint;
  v_entry jsonb;
  v_supply public.re_suministros%rowtype;
  v_qty numeric;
  v_count integer:=0;
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then raise exception using errcode='42501',message='Solo Recepción puede registrar entregas de Suministros.'; end if;
  if nullif(btrim(coalesce(p_entregado_a,'')),'') is null then raise exception 'Escribe el nombre de quien recibe.'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Agrega al menos un suministro.'; end if;
  v_folio:='RE-ENT-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(md5(random()::text),1,3));
  insert into public.re_entregas_suministros(folio,entregado_a,area,notas,firma_data)
  values(v_folio,btrim(p_entregado_a),nullif(btrim(coalesce(p_area,'')),''),nullif(btrim(coalesce(p_notas,'')),''),nullif(p_firma_data,'')) returning id into v_entrega_id;
  for v_entry in select value from jsonb_array_elements(p_items)
  loop
    v_qty:=greatest(coalesce((v_entry->>'cantidad')::numeric,0),0);
    if v_qty<=0 then continue; end if;
    select * into v_supply from public.re_suministros where id=(v_entry->>'suministro_id')::bigint and activo=true for update;
    if not found then raise exception 'Uno de los suministros ya no está disponible.'; end if;
    if coalesce(v_supply.stock,0)<v_qty then raise exception 'Existencia insuficiente de %. Disponible: % %.',v_supply.descripcion,v_supply.stock,v_supply.unidad; end if;
    update public.re_suministros set stock=stock-v_qty,updated_at=now() where id=v_supply.id;
    insert into public.re_entrega_suministro_items(entrega_id,suministro_id,descripcion,cantidad,unidad)
    values(v_entrega_id,v_supply.id,v_supply.descripcion,v_qty,v_supply.unidad);
    v_count:=v_count+1;
  end loop;
  if v_count=0 then raise exception 'No hay partidas válidas para entregar.'; end if;
  return jsonb_build_object('ok',true,'folio',v_folio,'entrega_id',v_entrega_id,'partidas',v_count);
end;
$$;
revoke all on function public.re_registrar_entrega_suministros_v108(text,text,text,text,jsonb) from public,anon;
grant execute on function public.re_registrar_entrega_suministros_v108(text,text,text,text,jsonb) to authenticated;

