-- ============================================================================
-- CRM V120 · RECEPCIÓN · SOLICITUDES DE SUMINISTROS POR QR
-- ============================================================================
begin;

create extension if not exists pgcrypto;

create table if not exists public.re_portal_solicitudes_config (
  id smallint primary key default 1 check (id = 1),
  token uuid not null default gen_random_uuid(),
  activo boolean not null default true,
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

insert into public.re_portal_solicitudes_config(id)
values(1)
on conflict(id) do nothing;

create table if not exists public.re_solicitudes_suministros (
  id bigint generated by default as identity primary key,
  folio text not null unique,
  solicitante text not null,
  area text not null,
  notas text,
  estado text not null default 'pendiente' check (estado in ('pendiente','entregada','rechazada')),
  motivo_rechazo text,
  entrega_id bigint references public.re_entregas_suministros(id) on update cascade on delete set null,
  atendida_por uuid references auth.users(id) on delete set null,
  fecha_atencion timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.re_solicitud_suministro_items (
  id bigint generated by default as identity primary key,
  solicitud_id bigint not null references public.re_solicitudes_suministros(id) on update cascade on delete cascade,
  suministro_id bigint not null references public.re_suministros(id) on update cascade on delete restrict,
  descripcion text not null,
  cantidad numeric(16,4) not null check (cantidad > 0),
  unidad text not null,
  created_at timestamptz not null default now(),
  unique(solicitud_id,suministro_id)
);

create index if not exists re_solicitudes_suministros_estado_idx on public.re_solicitudes_suministros(estado,created_at desc);
create index if not exists re_solicitud_suministro_items_solicitud_idx on public.re_solicitud_suministro_items(solicitud_id);

alter table public.re_portal_solicitudes_config enable row level security;
alter table public.re_solicitudes_suministros enable row level security;
alter table public.re_solicitud_suministro_items enable row level security;

drop policy if exists "Recepción consulta portal solicitudes" on public.re_portal_solicitudes_config;
create policy "Recepción consulta portal solicitudes" on public.re_portal_solicitudes_config
for select to authenticated
using (public.crm_usuario_tiene_rol(array['recepcion','administrador']));

drop policy if exists "Recepción administra solicitudes suministros" on public.re_solicitudes_suministros;
create policy "Recepción administra solicitudes suministros" on public.re_solicitudes_suministros
for all to authenticated
using (public.crm_usuario_tiene_rol(array['recepcion','administrador']))
with check (public.crm_usuario_tiene_rol(array['recepcion','administrador']));

drop policy if exists "Recepción administra partidas solicitudes suministros" on public.re_solicitud_suministro_items;
create policy "Recepción administra partidas solicitudes suministros" on public.re_solicitud_suministro_items
for all to authenticated
using (public.crm_usuario_tiene_rol(array['recepcion','administrador']))
with check (public.crm_usuario_tiene_rol(array['recepcion','administrador']));

grant select on public.re_portal_solicitudes_config to authenticated;
grant select,insert,update,delete on public.re_solicitudes_suministros,public.re_solicitud_suministro_items to authenticated;
grant usage,select on sequence public.re_solicitudes_suministros_id_seq,public.re_solicitud_suministro_items_id_seq to authenticated;

create or replace function public.re_portal_config_v120()
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_row public.re_portal_solicitudes_config%rowtype;
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then
    raise exception using errcode='42501',message='Solo Recepción puede administrar el QR de solicitudes.';
  end if;
  select * into v_row from public.re_portal_solicitudes_config where id=1;
  if not found then
    insert into public.re_portal_solicitudes_config(id,updated_by) values(1,auth.uid()) returning * into v_row;
  end if;
  return jsonb_build_object('ok',true,'token',v_row.token::text,'activo',v_row.activo,'updated_at',v_row.updated_at);
end;
$$;

create or replace function public.re_rotar_portal_solicitudes_v120()
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_token uuid:=gen_random_uuid();
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then
    raise exception using errcode='42501',message='Solo Recepción puede renovar el QR de solicitudes.';
  end if;
  insert into public.re_portal_solicitudes_config(id,token,activo,updated_by,updated_at)
  values(1,v_token,true,auth.uid(),now())
  on conflict(id) do update
    set token=excluded.token,activo=true,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
  return jsonb_build_object('ok',true,'token',v_token::text,'activo',true);
end;
$$;

create or replace function public.re_portal_catalogo_suministros_v120(p_token text)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_items jsonb;
begin
  if nullif(btrim(coalesce(p_token,'')),'') is null or not exists(
    select 1 from public.re_portal_solicitudes_config
    where id=1 and activo=true and token::text=btrim(p_token)
  ) then
    raise exception using errcode='42501',message='Este QR no está vigente. Solicita a Recepción el QR actual.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id',s.id,
      'descripcion',s.descripcion,
      'categoria',s.categoria,
      'unidad',s.unidad,
      'imagen',coalesce(s.imagen_url,'')
    ) order by lower(s.categoria),lower(s.descripcion)),'[]'::jsonb)
  into v_items
  from public.re_suministros s
  where s.activo=true and coalesce(s.stock,0)>0;

  return jsonb_build_object('ok',true,'items',v_items);
end;
$$;

create or replace function public.re_crear_solicitud_suministros_v120(
  p_token text,
  p_solicitante text,
  p_area text,
  p_notas text,
  p_items jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_id bigint;
  v_folio text;
  v_item jsonb;
  v_supply public.re_suministros%rowtype;
  v_supply_id bigint;
  v_qty numeric;
  v_count integer:=0;
begin
  if nullif(btrim(coalesce(p_token,'')),'') is null or not exists(
    select 1 from public.re_portal_solicitudes_config
    where id=1 and activo=true and token::text=btrim(p_token)
  ) then
    raise exception using errcode='42501',message='Este QR no está vigente. Solicita a Recepción el QR actual.';
  end if;
  if length(btrim(coalesce(p_solicitante,'')))<3 then raise exception 'Escribe tu nombre completo.'; end if;
  if length(btrim(coalesce(p_area,'')))<2 then raise exception 'Indica tu área, proyecto o motivo.'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Agrega al menos un suministro.'; end if;
  if jsonb_array_length(p_items)>20 then raise exception 'Una solicitud puede contener máximo 20 suministros.'; end if;

  v_folio:='RE-SOL-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISSMS')||'-'||upper(substr(md5(random()::text),1,3));
  insert into public.re_solicitudes_suministros(folio,solicitante,area,notas)
  values(
    v_folio,
    left(btrim(p_solicitante),120),
    left(btrim(p_area),160),
    nullif(left(btrim(coalesce(p_notas,'')),800),'')
  ) returning id into v_id;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    if coalesce(v_item->>'suministro_id','') !~ '^\\d+$' then continue; end if;
    v_supply_id:=(v_item->>'suministro_id')::bigint;
    begin
      v_qty:=(v_item->>'cantidad')::numeric;
    exception when others then
      v_qty:=0;
    end;
    v_qty:=greatest(coalesce(v_qty,0),0);
    if v_qty<=0 or v_qty>9999 then continue; end if;
    select * into v_supply from public.re_suministros where id=v_supply_id and activo=true;
    if not found then continue; end if;
    insert into public.re_solicitud_suministro_items(solicitud_id,suministro_id,descripcion,cantidad,unidad)
    values(v_id,v_supply.id,v_supply.descripcion,v_qty,v_supply.unidad)
    on conflict(solicitud_id,suministro_id) do update
      set cantidad=public.re_solicitud_suministro_items.cantidad+excluded.cantidad;
    v_count:=v_count+1;
  end loop;

  if v_count=0 then
    delete from public.re_solicitudes_suministros where id=v_id;
    raise exception 'No hay suministros válidos en la solicitud.';
  end if;

  return jsonb_build_object('ok',true,'folio',v_folio,'solicitud_id',v_id,'partidas',v_count);
end;
$$;

create or replace function public.re_entregar_solicitud_suministros_v120(p_solicitud_id bigint)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_request public.re_solicitudes_suministros%rowtype;
  v_item public.re_solicitud_suministro_items%rowtype;
  v_supply public.re_suministros%rowtype;
  v_delivery_id bigint;
  v_delivery_folio text;
  v_count integer:=0;
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then
    raise exception using errcode='42501',message='Solo Recepción puede entregar solicitudes.';
  end if;
  select * into v_request from public.re_solicitudes_suministros where id=p_solicitud_id for update;
  if not found then raise exception 'La solicitud ya no existe.'; end if;
  if v_request.estado<>'pendiente' then raise exception 'Esta solicitud ya fue atendida.'; end if;

  for v_item in select * from public.re_solicitud_suministro_items where solicitud_id=v_request.id order by id
  loop
    select * into v_supply from public.re_suministros where id=v_item.suministro_id and activo=true for update;
    if not found then raise exception 'El suministro % ya no está disponible.',v_item.descripcion; end if;
    if coalesce(v_supply.stock,0)<v_item.cantidad then
      raise exception 'No hay existencia suficiente de %. Disponible: % %; solicitado: % %.',v_supply.descripcion,v_supply.stock,v_supply.unidad,v_item.cantidad,v_item.unidad;
    end if;
  end loop;

  v_delivery_folio:='RE-ENT-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(md5(random()::text),1,3));
  insert into public.re_entregas_suministros(folio,entregado_a,area,notas,firma_data,entregado_por)
  values(
    v_delivery_folio,
    v_request.solicitante,
    v_request.area,
    nullif(concat_ws(E'\n',nullif(v_request.notas,''),'Solicitud QR: '||v_request.folio),''),
    null,
    auth.uid()
  ) returning id into v_delivery_id;

  for v_item in select * from public.re_solicitud_suministro_items where solicitud_id=v_request.id order by id
  loop
    select * into v_supply from public.re_suministros where id=v_item.suministro_id and activo=true for update;
    update public.re_suministros set stock=stock-v_item.cantidad,updated_at=now() where id=v_supply.id;
    insert into public.re_entrega_suministro_items(entrega_id,suministro_id,descripcion,cantidad,unidad)
    values(v_delivery_id,v_supply.id,v_supply.descripcion,v_item.cantidad,v_supply.unidad);
    v_count:=v_count+1;
  end loop;

  if v_count=0 then raise exception 'La solicitud no contiene partidas.'; end if;

  update public.re_solicitudes_suministros
  set estado='entregada',entrega_id=v_delivery_id,atendida_por=auth.uid(),fecha_atencion=now(),updated_at=now()
  where id=v_request.id;

  return jsonb_build_object('ok',true,'solicitud_folio',v_request.folio,'entrega_folio',v_delivery_folio,'entrega_id',v_delivery_id,'partidas',v_count);
end;
$$;

create or replace function public.re_rechazar_solicitud_suministros_v120(p_solicitud_id bigint,p_motivo text default null)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_folio text;
begin
  if not public.crm_usuario_tiene_rol(array['recepcion','administrador']) then
    raise exception using errcode='42501',message='Solo Recepción puede atender solicitudes.';
  end if;
  update public.re_solicitudes_suministros
  set estado='rechazada',motivo_rechazo=nullif(left(btrim(coalesce(p_motivo,'')),500),''),atendida_por=auth.uid(),fecha_atencion=now(),updated_at=now()
  where id=p_solicitud_id and estado='pendiente'
  returning folio into v_folio;
  if v_folio is null then raise exception 'La solicitud ya fue atendida o no existe.'; end if;
  return jsonb_build_object('ok',true,'folio',v_folio,'estado','rechazada');
end;
$$;

