alter table public.perfiles_usuario add column if not exists firma_predeterminada_slot smallint not null default 1;
alter table public.perfiles_usuario drop constraint if exists perfiles_usuario_firma_predeterminada_v128_check;
alter table public.perfiles_usuario add constraint perfiles_usuario_firma_predeterminada_v128_check
check (firma_predeterminada_slot between 1 and 3);

update public.perfiles_usuario
set firma_predeterminada_slot = case
  when firma_predeterminada_slot=1 and nullif(btrim(coalesce(firma_data_url,'')),'') is not null then 1
  when firma_predeterminada_slot=2 and nullif(btrim(coalesce(firma_2_data_url,'')),'') is not null then 2
  when firma_predeterminada_slot=3 and nullif(btrim(coalesce(firma_3_data_url,'')),'') is not null then 3
  when nullif(btrim(coalesce(firma_data_url,'')),'') is not null then 1
  when nullif(btrim(coalesce(firma_2_data_url,'')),'') is not null then 2
  when nullif(btrim(coalesce(firma_3_data_url,'')),'') is not null then 3
  else 1
end;

create or replace function public.crm_mis_firmas_v128()
returns jsonb
language plpgsql
stable
security definer
set search_path=public,auth
as $$
declare
  v_profile public.perfiles_usuario%rowtype;
  v_default integer;
begin
  if auth.uid() is null then raise exception 'La sesión no está activa.'; end if;
  select * into v_profile from public.perfiles_usuario where id=auth.uid() and activo=true;
  if not found then raise exception 'No se encontró un perfil activo para esta cuenta.'; end if;

  v_default:=coalesce(v_profile.firma_predeterminada_slot,1);
  if (v_default=1 and nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is null)
     or (v_default=2 and nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is null)
     or (v_default=3 and nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is null) then
    v_default:=case
      when nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is not null then 1
      when nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is not null then 2
      when nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is not null then 3
      else 1
    end;
  end if;

  return jsonb_build_object(
    'predeterminada_slot',v_default,
    'firmas',jsonb_build_array(
      jsonb_build_object('slot',1,'nombre',coalesce(nullif(btrim(v_profile.firma_1_nombre),''),'Firma 1'),'configurada',nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is not null,'firma_data_url',coalesce(v_profile.firma_data_url,''),'actualizada_at',v_profile.firma_actualizada_at,'predeterminada',v_default=1 and nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is not null),
      jsonb_build_object('slot',2,'nombre',coalesce(nullif(btrim(v_profile.firma_2_nombre),''),'Firma 2'),'configurada',nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is not null,'firma_data_url',coalesce(v_profile.firma_2_data_url,''),'actualizada_at',v_profile.firma_2_actualizada_at,'predeterminada',v_default=2 and nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is not null),
      jsonb_build_object('slot',3,'nombre',coalesce(nullif(btrim(v_profile.firma_3_nombre),''),'Firma 3'),'configurada',nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is not null,'firma_data_url',coalesce(v_profile.firma_3_data_url,''),'actualizada_at',v_profile.firma_3_actualizada_at,'predeterminada',v_default=3 and nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is not null)
    )
  );
end;
$$;

create or replace function public.crm_guardar_mi_firma_v128(p_slot integer,p_nombre text,p_firma_data text)
returns jsonb
language plpgsql
security definer
set search_path=public,auth
as $$
declare
  v_slot integer:=coalesce(p_slot,1);
  v_name text:=nullif(btrim(coalesce(p_nombre,'')),'');
  v_data text:=nullif(btrim(coalesce(p_firma_data,'')),'');
  v_at timestamptz:=case when nullif(btrim(coalesce(p_firma_data,'')),'') is null then null else now() end;
  v_profile public.perfiles_usuario%rowtype;
  v_default integer;
begin
  if auth.uid() is null then raise exception 'La sesión no está activa.'; end if;
  if v_slot not between 1 and 3 then raise exception 'La firma seleccionada no es válida.'; end if;
  v_name:=coalesce(v_name,'Firma '||v_slot::text);
  if length(v_name)>60 then raise exception 'El nombre de la firma no puede exceder 60 caracteres.'; end if;
  if v_data is not null and v_data !~ '^data:image/png;base64,' then raise exception 'La firma debe guardarse como imagen PNG.'; end if;
  if v_data is not null and length(v_data)>500000 then raise exception 'La firma es demasiado grande. Usa una imagen más sencilla.'; end if;

  if v_slot=1 then
    update public.perfiles_usuario set firma_1_nombre=v_name,firma_data_url=v_data,firma_actualizada_at=v_at,updated_at=now() where id=auth.uid() and activo=true;
  elsif v_slot=2 then
    update public.perfiles_usuario set firma_2_nombre=v_name,firma_2_data_url=v_data,firma_2_actualizada_at=v_at,updated_at=now() where id=auth.uid() and activo=true;
  else
    update public.perfiles_usuario set firma_3_nombre=v_name,firma_3_data_url=v_data,firma_3_actualizada_at=v_at,updated_at=now() where id=auth.uid() and activo=true;
  end if;
  if not found then raise exception 'No se encontró un perfil activo para esta cuenta.'; end if;

  select * into v_profile from public.perfiles_usuario where id=auth.uid();
  v_default:=coalesce(v_profile.firma_predeterminada_slot,1);
  if v_data is not null and (
       (v_default=1 and nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is null)
    or (v_default=2 and nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is null)
    or (v_default=3 and nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is null)
  ) then
    v_default:=v_slot;
  elsif v_data is null and v_default=v_slot then
    v_default:=case
      when v_slot<>1 and nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is not null then 1
      when v_slot<>2 and nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is not null then 2
      when v_slot<>3 and nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is not null then 3
      else 1
    end;
  end if;
  update public.perfiles_usuario set firma_predeterminada_slot=v_default,updated_at=now() where id=auth.uid();

  return jsonb_build_object('ok',true,'slot',v_slot,'nombre',v_name,'configurada',v_data is not null,'actualizada_at',v_at,'predeterminada_slot',v_default);
end;
$$;

create or replace function public.crm_guardar_firma_predeterminada_v128(p_slot integer)
returns jsonb
language plpgsql
security definer
set search_path=public,auth
as $$
declare
  v_slot integer:=coalesce(p_slot,1);
  v_profile public.perfiles_usuario%rowtype;
  v_signature text;
  v_name text;
begin
  if auth.uid() is null then raise exception 'La sesión no está activa.'; end if;
  if v_slot not between 1 and 3 then raise exception 'La firma seleccionada no es válida.'; end if;
  select * into v_profile from public.perfiles_usuario where id=auth.uid() and activo=true;
  if not found then raise exception 'No se encontró un perfil activo para esta cuenta.'; end if;
  if v_slot=1 then v_signature:=nullif(btrim(coalesce(v_profile.firma_data_url,'')),'');v_name:=coalesce(nullif(btrim(v_profile.firma_1_nombre),''),'Firma 1');
  elsif v_slot=2 then v_signature:=nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'');v_name:=coalesce(nullif(btrim(v_profile.firma_2_nombre),''),'Firma 2');
  else v_signature:=nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'');v_name:=coalesce(nullif(btrim(v_profile.firma_3_nombre),''),'Firma 3'); end if;
  if v_signature is null then raise exception 'Primero configura % antes de marcarla como predeterminada.',v_name; end if;
  update public.perfiles_usuario set firma_predeterminada_slot=v_slot,updated_at=now() where id=auth.uid();
  return jsonb_build_object('ok',true,'predeterminada_slot',v_slot,'nombre',v_name);
end;
$$;

create or replace function public.co_firmar_orden_con_mi_firma_v128(p_orden text,p_tipo text,p_firma_slot integer default null)
returns jsonb
language plpgsql
security definer
set search_path=public,auth
as $$
declare
  v_order text:=btrim(coalesce(p_orden,''));
  v_type text:=lower(btrim(coalesce(p_tipo,'')));
  v_slot integer;
  v_profile public.perfiles_usuario%rowtype;
  v_signature text;
  v_signature_name text;
  v_existing public.co_orden_firmas%rowtype;
  v_row public.co_orden_firmas%rowtype;
  v_author public.co_orden_autoria%rowtype;
begin
  if auth.uid() is null then raise exception 'La sesión no está activa.'; end if;
  if v_order='' then raise exception 'La orden de compra no tiene número.'; end if;
  if v_type not in ('solicito','elaboro','reviso','aprobo') then raise exception 'El tipo de firma no es válido.'; end if;
  select * into v_profile from public.perfiles_usuario where id=auth.uid() and activo=true;
  if not found then raise exception 'Tu perfil no está activo.'; end if;

  v_slot:=coalesce(p_firma_slot,v_profile.firma_predeterminada_slot,1);
  if v_slot not between 1 and 3 then raise exception 'La firma seleccionada no es válida.'; end if;
  if v_slot=1 then v_signature:=nullif(btrim(coalesce(v_profile.firma_data_url,'')),'');v_signature_name:=coalesce(nullif(btrim(v_profile.firma_1_nombre),''),'Firma 1');
  elsif v_slot=2 then v_signature:=nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'');v_signature_name:=coalesce(nullif(btrim(v_profile.firma_2_nombre),''),'Firma 2');
  else v_signature:=nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'');v_signature_name:=coalesce(nullif(btrim(v_profile.firma_3_nombre),''),'Firma 3'); end if;

  if v_signature is null and p_firma_slot is null then
    if nullif(btrim(coalesce(v_profile.firma_data_url,'')),'') is not null then v_slot:=1;v_signature:=v_profile.firma_data_url;v_signature_name:=coalesce(nullif(btrim(v_profile.firma_1_nombre),''),'Firma 1');
    elsif nullif(btrim(coalesce(v_profile.firma_2_data_url,'')),'') is not null then v_slot:=2;v_signature:=v_profile.firma_2_data_url;v_signature_name:=coalesce(nullif(btrim(v_profile.firma_2_nombre),''),'Firma 2');
    elsif nullif(btrim(coalesce(v_profile.firma_3_data_url,'')),'') is not null then v_slot:=3;v_signature:=v_profile.firma_3_data_url;v_signature_name:=coalesce(nullif(btrim(v_profile.firma_3_nombre),''),'Firma 3'); end if;
  end if;
  if v_signature is null then raise exception 'La % no está configurada en tu perfil.',v_signature_name; end if;

  if not exists(select 1 from public.solicitudes_compra s where lower(coalesce(nullif(btrim(s.orden_compra),''),nullif(btrim(s.grupo_orden),''),''))=lower(v_order)) then
    raise exception 'No se encontró la orden de compra %.',v_order;
  end if;
  if v_type='elaboro' then
    select * into v_author from public.co_orden_autoria where orden_key=lower(v_order);
    if not found then raise exception 'Esta orden es anterior a V124 y no tiene elaborador registrado. Compras debe registrar primero quién la elaboró.'; end if;
    if v_author.elaborada_por<>auth.uid() then raise exception 'El recuadro Elaboró pertenece a %. Solo esa cuenta puede aprobarlo y colocar su propia firma.',v_author.elaborada_por_nombre; end if;
  end if;

  select * into v_existing from public.co_orden_firmas where lower(btrim(orden_compra))=lower(v_order) and tipo=v_type limit 1;
  if found and v_existing.user_id<>auth.uid() then raise exception 'El espacio % ya fue aprobado y firmado por otra cuenta.',v_type; end if;

  insert into public.co_orden_firmas(orden_compra,tipo,nombre,firma_data_url,firma_slot,firma_nombre_perfil,user_id,firmado_at,updated_at)
  values(v_order,v_type,coalesce(nullif(btrim(v_profile.nombre),''),coalesce(auth.jwt()->>'email','Usuario')),v_signature,v_slot,v_signature_name,auth.uid(),now(),now())
  on conflict(orden_compra,tipo) do update set nombre=excluded.nombre,firma_data_url=excluded.firma_data_url,firma_slot=excluded.firma_slot,firma_nombre_perfil=excluded.firma_nombre_perfil,user_id=excluded.user_id,firmado_at=excluded.firmado_at,updated_at=excluded.updated_at
  where public.co_orden_firmas.user_id=auth.uid()
  returning * into v_row;
  if v_row.id is null then raise exception 'No se pudo registrar la aprobación.'; end if;
  return jsonb_build_object('ok',true,'id',v_row.id,'orden_compra',v_row.orden_compra,'tipo',v_row.tipo,'nombre',v_row.nombre,'user_id',v_row.user_id,'firmado_at',v_row.firmado_at,'firma_slot',v_slot,'firma_nombre',v_signature_name,'predeterminada',v_slot=coalesce(v_profile.firma_predeterminada_slot,1));
end;
$$;

